let GEMINI_MODEL = process.env.GEMINI_MODEL || 'gemini-2.5-flash-lite'; // primary — cheapest; set GEMINI_MODEL env to override
// Dedicated, stronger model for the AI Citations Tracker specifically (citation/GSC/source briefs,
// merge, ranking) — these need reliable multi-part structural compliance (exact headings, exact
// system labels) more than raw speed. Kept SEPARATE from the platform-wide GEMINI_MODEL so a change
// here never affects the Content Engine, SEO Audit, or any other feature. Falls back to GEMINI_MODEL
// automatically per-call if a gemini-2.5-pro request ever 404s (not available on this API key/tier).
let GEMINI_MODEL_BRIEF = process.env.GEMINI_MODEL_BRIEF || 'gemini-2.5-flash-lite';

async function detectBestGeminiModel(apiKey) {
  if (!apiKey) return;
  // Priority: cheapest postpay models first (billing enabled account)
  // gemini-2.0-flash = $0.075/1M tokens — best price/quality for postpay
  const PRIORITY = ['gemini-3.5-flash', 'gemini-3.5-flash-lite', 'gemini-3.1-flash-lite', 'gemini-2.5-flash'];
  try {
    const resp = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}`,
      { headers: { 'Content-Type': 'application/json' } }
    );
    if (!resp.ok) {
      console.warn('⚠️ Could not list Gemini models, using default:', GEMINI_MODEL);
      return;
    }
    const data = await resp.json();
    const available = (data.models || []).map(m => m.name.replace('models/', ''));
    console.log(`📋 Gemini models available: ${available.filter(m=>m.includes('flash')).join(', ')}`);
    // Pick first from priority list that exists
    for (const preferred of PRIORITY) {
      if (available.includes(preferred)) {
        GEMINI_MODEL = preferred;
        console.log(`✅ Gemini model selected: ${GEMINI_MODEL}`);
        return;
      }
    }
    // Fallback: any flash model
    const anyFlash = available.find(m => m.includes('flash') && !m.includes('thinking'));
    if (anyFlash) { GEMINI_MODEL = anyFlash; console.log(`✅ Gemini model fallback: ${GEMINI_MODEL}`); }
  } catch(e) {
    console.warn('⚠️ Gemini detect failed, using default:', GEMINI_MODEL, e.message);
  }
}

// Call Gemini with automatic fallback to a secondary model on overload/quota errors.
// Returns: { ok, status, data, modelUsed, errorMessage }
// Strategy: Flash-Lite → Flash → Perplexity Sonar → Claude Sonnet (best quality) → Claude Haiku (last resort)
async function callGeminiWithFallback(apiKey, body, primaryModel, fallbackModel, maxRetries = 3) {
  const FALLBACK = fallbackModel || 'gemini-2.5-flash';
  const primary = primaryModel || GEMINI_MODEL;
  const shouldRetry = (status, errMsg) => {
    if (status === 0 || status === 404 || status === 408 || status === 503 || status === 429 || status === 500 || status === 502) return true; // 0 = network/fetch error, 404 = model not found/unavailable on this key
    const m = (errMsg || '').toLowerCase();
    return m.includes('fetch failed') || m.includes('network') || m.includes('econnreset') || m.includes('enotfound') || m.includes('socket') || m.includes('overload') || m.includes('high demand') || m.includes('unavailable') || m.includes('rate limit') || m.includes('quota') || m.includes('timeout') || m.includes('timed out');
  };
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  const tryModel = async (model, attemptNum) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 90000);
    try {
      const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: controller.signal
      });
      clearTimeout(timer);
      const data = await resp.json().catch(() => ({}));
      return { ok: resp.ok, status: resp.status, data, modelUsed: model, errorMessage: data?.error?.message || '' };
    } catch (fetchErr) {
      clearTimeout(timer);
      if (fetchErr.name === 'AbortError') {
        return { ok: false, status: 408, data: {}, modelUsed: model, errorMessage: 'Gemini request timed out after 90s' };
      }
      return { ok: false, status: 0, data: {}, modelUsed: model, errorMessage: fetchErr.message || 'Network error' };
    }
  };

  // PHASE 1: Retry primary model with exponential backoff
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const result = await tryModel(primary, attempt);
    if (result.ok) return result;
    if (shouldRetry(result.status, result.errorMessage) && attempt < maxRetries) {
      const delay = Math.min(1000 * Math.pow(2, attempt) + Math.random() * 1000, 15000); // 2s, 4s, 8s max 15s
      console.warn(`⚠️ Gemini ${primary} attempt ${attempt}/${maxRetries} failed: "${result.errorMessage || result.status}" — retrying in ${Math.round(delay/1000)}s...`);
      await sleep(delay);
    } else if (!shouldRetry(result.status, result.errorMessage)) {
      return result; // Hard error, don't retry
    } else {
      console.warn(`⚠️ Gemini ${primary} exhausted all ${maxRetries} retries`);
    }
  }

  // PHASE 2: Try fallback Gemini model once
  if (primary !== FALLBACK) {
    console.warn(`🔄 Falling back to Gemini ${FALLBACK}...`);
    const fb = await tryModel(FALLBACK, 1);
    if (fb.ok) { console.log(`✅ Gemini fallback (${FALLBACK}) succeeded`); return fb; }
    console.warn(`⚠️ Gemini fallback (${FALLBACK}) also failed: "${fb.errorMessage || fb.status}"`);
  }

  // PHASE 3: Cross-provider fallback to Perplexity Sonar — for research/analysis
  const perplexityKey = process.env.PERPLEXITY_API_KEY;
  const userPrompt = body?.contents?.[0]?.parts?.[0]?.text || '';
  if (process.env.ALLOW_PERPLEXITY_FALLBACK === '1' && perplexityKey && userPrompt.length > 50) {
    console.warn(`🔄 Cross-provider fallback: trying Perplexity Sonar...`);
    try {
      const pxRes = await fetch('https://api.perplexity.ai/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${perplexityKey}` },
        body: JSON.stringify({
          model: 'sonar',
          messages: [{ role: 'user', content: userPrompt }],
          max_tokens: 4000
        })
      });
      if (pxRes.ok) {
        const pxJson = await pxRes.json();
        const pxText = pxJson.choices?.[0]?.message?.content || '';
        if (pxText.length > 100) {
          console.log(`✅ Perplexity fallback succeeded (${pxText.length} chars)`);
          // Track Perplexity cost
          const pxUsage = pxJson.usage || {};
          const pxCost = (pxUsage.prompt_tokens||0) * 1e-6 + (pxUsage.completion_tokens||0) * 1e-6;
          if (pxCost > 0) {
            const codeId = body?._codeId;
            if (codeId) trackApiCost(codeId, 'fallback-perplexity', 'perplexity-sonar', pxUsage.prompt_tokens||0, pxUsage.completion_tokens||0, 'Perplexity fallback').catch(()=>{});
          }
          // Normalize to Gemini format
          return { ok: true, status: 200, data: { candidates: [{ content: { parts: [{ text: pxText }] } }] }, modelUsed: 'perplexity-sonar', errorMessage: '' };
        }
      }
    } catch(pxErr) {
      console.warn(`⚠️ Perplexity fallback also failed: ${pxErr.message}`);
    }
  }

  // PHASE 4: Claude Sonnet — best quality Claude fallback with web search
  const claudeKey = process.env.ANTHROPIC_API_KEY;
  if (process.env.ALLOW_CLAUDE_FALLBACK === '1' && claudeKey && userPrompt.length > 50) {
    console.warn(`🔄 Phase 4: Claude Sonnet with web search...`);
    try {
      claudeGuard.gate();
        const sonnet4Res = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': claudeKey, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'web-search-2025-03-05' },
        body: JSON.stringify({
          model: 'claude-sonnet-4-6',
          max_tokens: 4000,
          tools: [{ type: 'web_search_20250305', name: 'web_search' }],
          messages: [{ role: 'user', content: userPrompt }]
        })
      });
      if (sonnet4Res.ok) {
        const s4Json = await sonnet4Res.json();
        const s4Text = (s4Json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
        if (s4Text.length > 100) {
          console.log(`✅ Claude Sonnet phase 4 succeeded`);
          return { ok: true, status: 200, data: { candidates: [{ content: { parts: [{ text: s4Text }] } }] }, modelUsed: 'claude-sonnet-4-6', errorMessage: '' };
        }
      }
    } catch(e) {
      console.warn(`⚠️ Claude Sonnet phase 4 failed: ${e.message}`);
    }
  }

  // PHASE 5: Last resort — Claude Haiku with web search
  if (process.env.ALLOW_CLAUDE_FALLBACK === '1' && claudeKey && userPrompt.length > 50) {
    console.warn(`🔄 Phase 5 fallback: Claude Sonnet with web search...`);
    try {
      claudeGuard.gate();
        const sonnetRes = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': claudeKey, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'web-search-2025-03-05' },
        body: JSON.stringify({
          model: 'claude-sonnet-4-6',
          max_tokens: 4000,
          tools: [{ type: 'web_search_20250305', name: 'web_search' }],
          messages: [{ role: 'user', content: userPrompt }]
        })
      });
      if (sonnetRes.ok) {
        const sonnetJson = await sonnetRes.json();
        const sonnetText = (sonnetJson.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
        if (sonnetText.length > 100) {
          console.log(`✅ Claude Sonnet phase 5 fallback succeeded`);
          return { ok: true, status: 200, data: { candidates: [{ content: { parts: [{ text: sonnetText }] } }] }, modelUsed: 'claude-haiku-4-5-20251001', errorMessage: '' };
        }
      }
    } catch(e) {
      console.warn(`⚠️ Claude Haiku last resort also failed: ${e.message}`);
    }
  }

  // All providers exhausted
  return { ok: false, status: 503, data: {}, modelUsed: 'all-exhausted', errorMessage: 'All AI providers (Gemini Flash-Lite → Flash → Perplexity → Haiku → Sonnet) are busy. Wait 30-60 seconds and retry.' };
}

// ── Gemini & AI Provider Status Monitor ─────────────────────────────────────
// Tracks rate limits, errors, and availability across all AI providers in real-time
const _aiProviderStatus = {
  gemini_primary: { ok: true, lastError: null, lastErrorAt: null, errorCount: 0, lastOkAt: Date.now(), consecutiveErrors: 0 },
  gemini_flash:   { ok: true, lastError: null, lastErrorAt: null, errorCount: 0, lastOkAt: Date.now(), consecutiveErrors: 0 },
  perplexity:     { ok: true, lastError: null, lastErrorAt: null, errorCount: 0, lastOkAt: Date.now(), consecutiveErrors: 0 },
  claude:         { ok: true, lastError: null, lastErrorAt: null, errorCount: 0, lastOkAt: Date.now(), consecutiveErrors: 0 },
  serper:         { ok: true, lastError: null, lastErrorAt: null, errorCount: 0, lastOkAt: Date.now(), consecutiveErrors: 0 },
  bing:           { ok: true, lastError: null, lastErrorAt: null, errorCount: 0, lastOkAt: Date.now(), consecutiveErrors: 0 },
  brave:          { ok: true, lastError: null, lastErrorAt: null, errorCount: 0, lastOkAt: Date.now(), consecutiveErrors: 0 },
};
const _aiProviderHistory = []; // last 50 calls

function _trackAiCall(provider, model, success, errorMsg, durationMs) {
  const key = model && model.includes('flash') ? 'gemini_flash'
    : model && (model.includes('gemini') || model.includes('Gemini')) ? 'gemini_primary'
    : model && model.includes('perplexity') ? 'perplexity'
    : model && model.includes('claude') ? 'claude'
    : model && model.includes('bing') ? 'bing'
    : model && model.includes('brave') ? 'brave'
    : provider === 'bing' ? 'bing'
    : provider === 'brave' ? 'brave'
    : provider || 'gemini_primary';

  const s = _aiProviderStatus[key] || _aiProviderStatus['gemini_primary'];
  const now = Date.now();
  if (success) {
    s.ok = true; s.consecutiveErrors = 0; s.lastOkAt = now;
    s.lastError = null;
  } else {
    s.consecutiveErrors = (s.consecutiveErrors || 0) + 1;
    s.errorCount = (s.errorCount || 0) + 1;
    s.lastError = errorMsg || 'unknown error';
    s.lastErrorAt = new Date().toISOString();
    // Mark as down after 3 consecutive errors
    if (s.consecutiveErrors >= 3) s.ok = false;
  }

  // Keep last 50 call history
  _aiProviderHistory.unshift({
    provider: key, model: model || key, success,
    error: success ? null : (errorMsg || '').substring(0, 100),
    durationMs: durationMs || 0,
    at: new Date().toISOString()
  });
  if (_aiProviderHistory.length > 50) _aiProviderHistory.pop();
}



// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// callClaudeForWrite — ALL writing goes through Claude
// Gemini = research/JSON only · Claude = every HTML output
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// -- Claude circuit breaker: auto-stops runaway AI spend ---------------------
const claudeGuard = (() => {
  const WINDOW_MS   = parseInt(process.env.CLAUDE_WINDOW_MS) || 300000;
  const MAX_CALLS   = parseInt(process.env.CLAUDE_MAX_CALLS) || 40;
  const COOLDOWN_MS = parseInt(process.env.CLAUDE_COOLDOWN_MS) || 600000;
  let calls = [], trippedUntil = 0, lastAlert = 0;
  function notify(msg){
    try{
      if(Date.now()-lastAlert>60000){ lastAlert=Date.now();
        notifyOttmar('⚠️ Claude circuit breaker', '<p>' + msg + '</p>', msg).catch(()=>{}); } }catch(_){}
  }
  return {
    gate(){
      const now=Date.now();
      if(now<trippedUntil) throw new Error('Claude circuit breaker OPEN - AI calls blocked to prevent runaway cost. Resets '+new Date(trippedUntil).toISOString()+'.');
      calls=calls.filter(t=>now-t<WINDOW_MS); calls.push(now);
      if(calls.length>MAX_CALLS){ trippedUntil=now+COOLDOWN_MS; calls=[];
        const m='ALERT ContentScale: Claude circuit breaker TRIPPED - too many AI calls. Blocking for '+Math.round(COOLDOWN_MS/60000)+'min.';
        console.error(m); notify(m);
        throw new Error('Claude circuit breaker tripped - AI calls blocked.'); }
    },
    status(){ const now=Date.now(); calls=calls.filter(t=>now-t<WINDOW_MS); return {open:now<trippedUntil, trippedUntil, calls_in_window:calls.length, max_calls:MAX_CALLS, window_minutes:Math.round(WINDOW_MS/60000)}; },
    reset(){ trippedUntil=0; calls=[]; return true; }
  };
})();

async function callClaudeForWrite(systemPrompt, userPrompt, maxTokens = 8000, claudeKey, modelName = 'claude-sonnet-4-6') {
  const anthropicKey = claudeKey || process.env.ANTHROPIC_API_KEY;
  if (!anthropicKey) throw new Error('Claude API key required — add ANTHROPIC_API_KEY to Railway or provide x-claude-key header');
  claudeGuard.gate();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 55000); // 55s — under Railway limit
  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({ model: modelName, max_tokens: maxTokens, system: systemPrompt, messages: [{ role: 'user', content: userPrompt }] }),
      signal: controller.signal,
    });
    clearTimeout(timer);
    const data = await r.json();
    if (!r.ok) throw new Error(`Claude API ${r.status}: ${data.error?.message || JSON.stringify(data)}`);
    const text = data?.content?.[0]?.text || '';
    if (!text) throw new Error('Claude returned empty content');
    return text;
  } catch(e) { clearTimeout(timer); throw e; }
}


// Auto-split long paragraphs — enforces max 2 sentences per <p>
// Applied to all generated HTML output across write, rewrite, news, video routes
function splitLongParagraphs(html) {
  if (!html) return html;
  return html.replace(/<p([^>]*)>([\s\S]*?)<\/p>/gi, (match, attrs, content) => {
    // Skip paragraphs containing block-level HTML — don't break structured components
    if (/<(?:div|ul|ol|li|table|blockquote|h[1-6]|img|figure)/i.test(content)) return match;
    // Skip very short content
    if (content.trim().length < 80) return match;
    // Split on sentence boundaries — period/!/? followed by space + capital or end
    const sentences = content.match(/[^.!?]*[.!?]+(?:\s+|$)/g);
    if (!sentences || sentences.length <= 2) return match;
    // Group into pairs of 2 sentences max
    const groups = [];
    for (let i = 0; i < sentences.length; i += 2) {
      const group = sentences.slice(i, i + 2).join('').trim();
      if (group) groups.push(group);
    }
    if (groups.length <= 1) return match;
    return groups.map(g => `<p${attrs}>${g}</p>`).join('\n');
  });
}

// Strip AI-inserted placeholder/flag patterns from generated HTML content.
// Used by both the article write endpoint and the news rewrite endpoint.
function stripAiPlaceholders(html) {
  if (!html) return html;
  const patterns = [
    /\s*[·\-—|]*\s*\[CONFIDENCE[^\]]*\]/gi,
    /\s*[·\-—|]*\s*\[UNVERIFIED[^\]]*\]/gi,
    /\s*[·\-—|]*\s*\[FLAG[^\]]*\]/gi,
    /\s*[·\-—|]*\s*\[bron\s+nodig[^\]]*\]/gi,
    /\s*[·\-—|]*\s*\[citation\s+needed[^\]]*\]/gi,
    /\s*[·\-—|]*\s*\[NEEDS\s+VERIFICATION[^\]]*\]/gi,
    /\s*[·\-—|]*\s*\[TODO[^\]]*\]/gi,
  ];
  let out = html, hits = 0;
  patterns.forEach(re => { const b = out.length; out = out.replace(re, ''); if (out.length !== b) hits++; });
  return { html: out, stripped: hits };
}

