async function sendTrackerEmail(clientId, subject, htmlBody, hideViewBtn) {
  if (subject && subject.indexOf('[TRACKER]') !== 0) subject = '[TRACKER] ' + subject;
  try {
    // Robust query — handle missing columns gracefully
    let client;
    try {
      const cr = await pool.query('SELECT * FROM tracker_clients WHERE id=$1 AND (email_unsubscribed IS NULL OR email_unsubscribed=FALSE) AND (emails_paused IS NULL OR emails_paused=FALSE) AND email IS NOT NULL', [clientId]);
      if (!cr.rows.length) {
        console.warn('[tracker-email] No client found, unsubscribed, or paused for id:', clientId);
        return;
      }
      client = cr.rows[0];
    } catch(qErr) {
      // Fallback if email_unsubscribed column doesn't exist
      const cr2 = await pool.query('SELECT * FROM tracker_clients WHERE id=$1 AND email IS NOT NULL', [clientId]);
      if (!cr2.rows.length) { console.warn('[tracker-email] No client with email for id:', clientId); return; }
      client = cr2.rows[0];
    }

    // Generate unsubscribe token if not set
    let unsubToken = client.unsubscribe_token || null;
    if (!unsubToken) {
      unsubToken = require('crypto').randomBytes(20).toString('hex');
      try { await pool.query('UPDATE tracker_clients SET unsubscribe_token=$1 WHERE id=$2', [unsubToken, clientId]); } catch(e) {}
    }

    const unsubUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/unsubscribe/' + unsubToken;
    const trackUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + client.token;
    const liveUrl = trackUrl + '/live';

    const fullHtml = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f1f5f9;font-family:Verdana,Geneva,sans-serif;">
<div style="max-width:600px;margin:0 auto;padding:32px 16px;">
  <div style="background:#0f172a;border-radius:12px 12px 0 0;padding:24px 32px;text-align:center;">
    <div style="font-size:20px;font-weight:800;color:#ffffff;">ContentScale</div>
    <div style="font-size:10px;color:#64748b;margin-top:4px;text-transform:uppercase;letter-spacing:.1em;">AI Citation Tracker</div>
  </div>
  <div style="background:#ffffff;padding:32px;border-left:1px solid #e2e8f0;border-right:1px solid #e2e8f0;">
    ${htmlBody}
    ${hideViewBtn ? '' : `<div style="margin-top:32px;text-align:center;">
      <a href="${liveUrl}" style="display:inline-block;background:#7c3aed;color:#ffffff;text-decoration:none;padding:12px 28px;border-radius:8px;font-weight:700;font-size:14px;">View Your Tracker</a>
    </div>`}
  </div>
  <div style="background:#f5f3ff;border:1px solid #ddd6fe;padding:20px 32px;text-align:center;">
    <div style="font-size:13px;font-weight:700;color:#1e293b;margin-bottom:6px;">Want Ottmar to implement these changes for you?</div>
    <div style="font-size:12px;color:#64748b;margin-bottom:12px;">Book a free strategy call — Done-for-you AI citation optimization &mdash; high-GRAAF, citation-ready content.</div>
    <a href="https://calendly.com/aioeditors" style="display:inline-block;background:#0f172a;color:#ffffff;text-decoration:none;padding:10px 20px;border-radius:6px;font-size:12px;font-weight:700;">Book Free Strategy Call</a>
  </div>
  <div style="background:#f8fafc;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 12px 12px;padding:20px 32px;text-align:center;">
    <div style="font-size:11px;color:#94a3b8;line-height:1.8;">
      ContentScale &middot; Amsterdam &middot; <a href="https://contentscale.site" style="color:#7c3aed;text-decoration:none;">contentscale.site</a><br>
      You are receiving this because you registered a free tracker for <strong>${client.domain}</strong>.<br>
      <a href="${unsubUrl}" style="color:#cbd5e1;text-decoration:underline;font-size:10px;">Unsubscribe from tracker updates</a>
    </div>
  </div>
</div>
</body></html>`;

    const brevoKey = process.env.BREVO_API_KEY || '';
    if (!brevoKey) { console.warn('[tracker-email] No email API key (BREVO_API_KEY)'); return; }

    const _ccList = String(client.cc_emails || '').split(',').map(e => e.trim()).filter(e => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e));
    const _recipients = [{ email: client.email, name: client.name || client.email }]
      .concat(_ccList.filter(e => e.toLowerCase() !== String(client.email || '').toLowerCase()).map(e => ({ email: e })));
    const resp = await fetch('https://api.brevo.com/v3/smtp/email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'api-key': brevoKey },
      body: JSON.stringify({
        to: _recipients,
        sender: { email: process.env.FROM_EMAIL || 'info@contentscale.site', name: process.env.SENDER_NAME || 'ContentScale Tracker' },
        subject: subject,
        htmlContent: fullHtml
      })
    });
    if (!resp.ok) {
      const err = await resp.text().catch(()=>'');
      console.warn('[tracker-email] Brevo error', resp.status, err.substring(0,200));
    } else {
      console.log('[tracker-email] Sent via Brevo to', client.email);
      // Broadcast email_sent event so client sees in-app notification
      if (typeof _sseBroadcast === 'function') {
        _sseBroadcast({ type: 'email_sent', clientId: clientId, domain: client.domain || '', email: client.email, subject: subject, ts: new Date().toISOString() });
      }
    }
  } catch(e) { console.warn('[tracker-email] Failed:', e.message); }
}

// ── GET /api/tracker-client/register ─────────────────────────────────────────

function generateClientToken() {
  return require('crypto').randomBytes(24).toString('hex');
}

// Ensure a client has a read-only share token; create one if missing. Returns the token.
// Called at account creation and lazily in any email path, so the RO link ALWAYS exists.
async function ensureReadonlyToken(clientId) {
  try {
    const r = await pool.query('SELECT readonly_token FROM tracker_clients WHERE id=$1', [clientId]);
    if (!r.rows.length) return null;
    if (r.rows[0].readonly_token) return r.rows[0].readonly_token;
    const roToken = 'ro_' + generateClientToken();
    await pool.query('UPDATE tracker_clients SET readonly_token=$1 WHERE id=$2', [roToken, clientId]);
    return roToken;
  } catch(e) { return null; }
}

// Reusable email block showing BOTH links with an unmistakable distinction.
