// POST /api/tracker-client/register — create new client tracker
// ── DEMO READ-ONLY GUARD ─────────────────────────────────────────────────
// A client flagged demo_readonly=TRUE (admin toggle) gets a fully browsable tracker,
// but every mutation (POST/PATCH/PUT/DELETE) is blocked server-side. This makes the
// share link safe to hand to prospects: they can look at everything, change nothing.
// Small in-memory cache for the RO-token lookup: avoids one extra DB roundtrip per tracker request
// (this middleware runs on EVERY /api/tracker-client/* call, including the owner's own normal traffic).
// 60s TTL — a freshly created RO link works within a minute; negative results cache too, so a normal
// owner token (99% of traffic) costs one cheap Map lookup instead of a query after the first hit.
const _roTokenCache = new Map(); // tok -> { owner: string|null, at: number }
app.use(async (req, res, next) => {
  // Read-only SHARE token guard. NOTE: must be a GLOBAL middleware — mounting on
  // '/api/tracker-client/:token' makes Express strip the prefix from req.url, so a
  // rewrite there never reaches the routers (the original bug: "Tracker not found").
  const m = req.path.match(/^\/api\/tracker-client\/([^\/]+)/);
  if (!m || m[1] === 'register') return next();
  const tok = m[1];
  try {
    let _cached = _roTokenCache.get(tok);
    if (!_cached || (Date.now() - _cached.at) > 60000) {
      const _ro = await pool.query('SELECT token FROM tracker_clients WHERE readonly_token=$1', [tok]);
      _cached = { owner: _ro.rows.length ? _ro.rows[0].token : null, at: Date.now() };
      _roTokenCache.set(tok, _cached);
      if (_roTokenCache.size > 5000) _roTokenCache.clear(); // simple guard against unbounded growth
    }
    const ro = { rows: _cached.owner ? [{ token: _cached.owner }] : [] };
    if (ro.rows.length) {
      if (req.method !== 'GET') return res.status(403).json({ success: false, error: 'Read-only link \u2014 viewing is live, changes are disabled.' });
      // Transparently rewrite to the owner token so every existing GET endpoint works unchanged
      req.url = req.url.replace('/api/tracker-client/' + tok, '/api/tracker-client/' + ro.rows[0].token);
      return next();
    }
    if (req.method !== 'GET') {
      const r = await pool.query('SELECT demo_readonly FROM tracker_clients WHERE token=$1', [tok]);
      if (r.rows.length && r.rows[0].demo_readonly === true) {
        return res.status(403).json({ success: false, error: 'This is a read-only view \u2014 the live data is real, but editing is disabled on the shared link.' });
      }
    }
  } catch(e) {}
  next();
});

app.post('/api/tracker-client/register', async (req, res) => {
  try {
    const { domain, name, email, whatsapp, dealify_code } = req.body;
    if (!domain) return res.status(400).json({ success: false, error: 'Domain required' });

    // Get client IP
    const clientIp = (req.headers['x-forwarded-for'] || req.socket.remoteAddress || '').split(',')[0].trim();

    // Clean domain
    const cleanDomain = domain.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase().trim();
    if (!cleanDomain || !cleanDomain.includes('.')) return res.status(400).json({ success: false, error: 'Invalid domain' });

    // Check if domain already registered — bulletproof: strip www, check base domain
    // Check if domain already registered — block ALL including deleted
    const baseDomain = cleanDomain.replace(/^www\./, '');
    const existing = await pool.query(
      `SELECT id, token, email, name, status FROM tracker_clients
       WHERE (
         LOWER(REGEXP_REPLACE(domain, '^www\\.', '')) = $1
         OR LOWER(domain) = $1
         OR LOWER(domain) = $2
       )
       ORDER BY CASE WHEN status='active' THEN 0 WHEN status='paused' THEN 1 ELSE 2 END
       LIMIT 1`,
      [baseDomain, 'www.' + baseDomain]
    );
    if (existing.rows.length) {
      // Never return existing tracker URL on public registration
      // Always direct to Ottmar — he handles it via admin
      const ex = existing.rows[0];
      notifyOttmar(
        '⚠️ Re-registration attempt: ' + cleanDomain,
        '<p>Domain: ' + cleanDomain + '<br>Status: ' + ex.status + '<br>Email: ' + (email || 'none') + '</p>',
        'Re-registration attempt: ' + cleanDomain + ' (status: ' + ex.status + ') — email: ' + (email || 'none')
      ).catch(() => {});
      return res.status(409).json({
        success: false,
        error: 'A tracker for ' + cleanDomain + ' already exists. Contact Ottmar to recover or reset your tracker: wa.me/31628073996'
      });
    }

    // Dealify code validation — format: DEALIFY-XXXXX (1-5 codes allowed)
    let maxPages = 1; // default free (was 3) — scan interval stays 3 days
    let dealifyCodesCount = 0;
    let isDealify = false;
    if (dealify_code) {
      // Accept comma-separated codes: "DEALIFY-ABC12, DEALIFY-DEF34"
      // Accepted code prefixes per platform
      const VALID_PREFIXES = ['DEALIFY-', 'CS-', 'APPSUMO-', 'AS-', 'PG-', 'PITCHGROUND-', 'SM-', 'SAASMANTRA-', 'LTD-', 'PRIME-'];
      const codes = dealify_code.split(',').map(c => c.trim().toUpperCase()).filter(c => VALID_PREFIXES.some(p => c.startsWith(p)));
      dealifyCodesCount = Math.min(codes.length, 5); // max 5 codes
      if (dealifyCodesCount > 0) {
        maxPages = dealifyCodesCount * 10; // 1 code = 10 pages, 2 = 20, etc.
        isDealify = true;
      }
    }

    // IP restriction — only for non-Dealify free registrations
    if (!isDealify && clientIp) {
      const ipCheck = await pool.query('SELECT COUNT(*) FROM tracker_clients WHERE registered_ip=$1', [clientIp]);
      if (parseInt(ipCheck.rows[0].count) >= 1) {
        return res.status(429).json({ success: false, error: 'One free tracker per device. Want more pages? Get lifetime access at contentscale.site/tracker' });
      }
    }

    const token = generateClientToken();
    await pool.query(
      `INSERT INTO tracker_clients (token, domain, name, email, whatsapp, max_pages, registered_ip, dealify_codes) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
      [token, cleanDomain, name||null, email||null, whatsapp||null, maxPages, clientIp||null, isDealify ? dealify_code : null]
    ).catch(async () => {
      // Fallback if dealify_codes column doesn't exist yet
      await pool.query(
        `INSERT INTO tracker_clients (token, domain, name, email, whatsapp, max_pages, registered_ip) VALUES ($1,$2,$3,$4,$5,$6,$7)`,
        [token, cleanDomain, name||null, email||null, whatsapp||null, maxPages, clientIp||null]
      );
    });

    // Live Brief Wall ("View tracker" page) is ON by default for every new domain
    try { await pool.query(`UPDATE tracker_clients SET live_wall_enabled=TRUE WHERE token=$1`, [token]); } catch(e) {}

    const trackUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + token;
    const appUrl = process.env.APP_URL || 'https://app.contentscale.site';

    // Send welcome email with tracker URL
    if (email) {
      const liveUrl = trackUrl + '/live';
      const welcomeHtml = '<h2 style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:10px;">Your AI Citations Tracker is ready</h2>'
        + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">Hi ' + (name || 'there') + ',<br><br>Your tracker for <strong>' + cleanDomain + '</strong> is set up. You have two links — they do different things:</p>'
        + '<div style="background:#f5f3ff;border:2px solid #c4b5fd;border-radius:8px;padding:16px;margin-bottom:14px;">'
        + '<div style="font-size:12px;font-weight:800;color:#6d28d9;text-transform:uppercase;letter-spacing:.04em;margin-bottom:4px;">&#128278; Bookmark this — your working scanner</div>'
        + '<div style="font-size:13px;color:#374151;line-height:1.6;margin-bottom:10px;">This is where you <strong>add pages, keywords, and paste HTML</strong>. Save it as a bookmark — it is your private link, do not share it.</div>'
        + '<div style="font-size:11px;font-family:monospace;color:#7c3aed;word-break:break-all;margin-bottom:10px;">' + trackUrl + '</div>'
        + '<a href="' + trackUrl + '" style="display:inline-block;background:#7c3aed;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">Open tracker &rarr;</a>'
        + '</div>'
        + '<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;margin-bottom:16px;">'
        + '<div style="font-size:12px;font-weight:800;color:#0f172a;text-transform:uppercase;letter-spacing:.04em;margin-bottom:4px;">&#128250; View Tracker — live results (TV mode)</div>'
        + '<div style="font-size:13px;color:#374151;line-height:1.6;margin-bottom:10px;">A read-only live wall of your citation results. Safe to share or leave on a screen.</div>'
        + '<a href="' + liveUrl + '" style="display:inline-block;background:#0f172a;color:white;text-decoration:none;padding:9px 20px;border-radius:6px;font-size:12px;font-weight:700;">View Tracker &rarr;</a>'
        + '</div>'
        + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;"><strong>What happens next:</strong><br>'
        + '1. Add your pages and keywords in the scanner<br>'
        + '2. Your first check runs automatically in ~1 minute<br>'
        + '3. Paste your page HTML for a full GRAAF score<br>'
        + '4. Your Citation Brief arrives by email</p>'
        + (isDealify ? '<p style="font-size:13px;color:#6b7280;margin-bottom:14px;">&#127881; Dealify activation: <strong>' + dealifyCodesCount + ' code' + (dealifyCodesCount>1?'s':'') + '</strong> &rarr; <strong>' + maxPages + ' pages</strong> tracked.</p>' : '')
        + '<p style="font-size:13px;color:#374151;line-height:1.7;">Questions? WhatsApp Ottmar directly: <a href="https://wa.me/31628073996" style="color:#7c3aed;">wa.me/31628073996</a></p>';

      const clientId = (await pool.query('SELECT id FROM tracker_clients WHERE token=$1', [token])).rows[0]?.id;
      if (clientId) await sendTrackerEmail(clientId, 'Your AI Citations Tracker is ready — ' + cleanDomain, welcomeHtml, true).catch(() => {});
    }

    // Notify Ottmar
    {
      // Detect platform from code prefix
      const platformMap = { 'APPSUMO-': 'AppSumo', 'AS-': 'AppSumo', 'PG-': 'PitchGround', 'PITCHGROUND-': 'PitchGround', 'SM-': 'SaasMantra', 'SAASMANTRA-': 'SaasMantra', 'DEALIFY-': 'Dealify', 'CS-': 'Direct', 'LTD-': 'LTD', 'PRIME-': 'Prime' };
      const detectedPlatform = codes.length > 0 ? (Object.entries(platformMap).find(([p]) => codes[0].startsWith(p)) || ['','Direct'])[1] : 'Direct';

      const msg = `New tracker: ${cleanDomain} (${name||'anon'}) ${isDealify ? '🎯 ' + detectedPlatform + ' ' + dealifyCodesCount + ' codes / ' + maxPages + ' pages' : '🆓 free'} — ${trackUrl}`;
      notifyOttmar('⭐ New tracker: ' + cleanDomain, '<p>' + msg + '</p>', msg).catch(() => {});
    }

    res.json({ success: true, token, domain: cleanDomain, url: trackUrl, existing: false, max_pages: maxPages, dealify: isDealify });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// GET /api/tracker-client/:token — get client data + pages
app.get('/api/tracker-client/:token', async (req, res) => {
  try {
    const cr = await pool.query('SELECT * FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Tracker not found. Check your link is correct.' });
    if (cr.rows[0].status === 'disabled' || cr.rows[0].status === 'paused') return res.status(403).json({ success: false, disabled: true, error: 'This tracker is ' + cr.rows[0].status + '. Contact Ottmar to reactivate.' });
    const client = cr.rows[0];

    // Ensure tracker_client_id column exists before querying
    const pagesR = await pool.query(
      `SELECT p.id, p.url, p.keyword, p.gsc_keyword, p.created_at, p.next_check_at, p.last_checked_at,
              p.is_done, p.manual_done, p.manual_done_at, p.fetch_reliable, p.check_frequency, p.gsc_clicks, p.gsc_impressions, p.gsc_position,
              p.ranking_brief, p.needs_html, p.brief_started_at, p.brief_content, p.brief_check_count,
              p.html_pasted_at, p.html_source, p.last_graaf_score,
              (p.html_content IS NOT NULL AND p.html_content != '') as has_html_content,
              p.redirects_to,
              p.gsc_autofetch_checked_at, p.aio_manual_text, p.aio_manual_refs, p.brief_viewed_at,
              s.google_position, s.ai_google_overview_cited, s.ai_google_overview_text, s.ai_google_overview_found, s.ai_perplexity_cited,
              s.ai_bing_cited, s.ai_bing_text, s.ai_brave_cited,
              s.score as graaf_score, s.checked_at as last_checked,
              s.recommendations, s.source_suggestions, s.discovered_sources,
              s.gsc_brief, s.author_trust_score, s.author_trust_findings,
              s.google_competitors, s.ai_perplexity_competitors, s.ai_perplexity_answer_excerpt, s.ai_perplexity_text, s.ai_google_overview_references
       FROM tracker_pages p
       LEFT JOIN LATERAL (
         SELECT * FROM tracker_snapshots WHERE page_id = p.id ORDER BY checked_at DESC LIMIT 1
       ) s ON true
       WHERE p.tracker_client_id = $1 AND (p.is_active = TRUE OR p.is_active IS NULL)
       ORDER BY p.created_at DESC LIMIT $2`,
      [client.id, client.max_pages || 3]
    );

    res.json({
      success: true,
      client: {
        domain: client.domain,
        name: client.name,
        max_pages: client.max_pages || 3,
        created_at: client.created_at,
        telegram_linked: !!client.telegram_chat_id,
        live_wall_enabled: !!client.live_wall_enabled,
        brand_context: client.brand_context || '',
        sitemap_url: client.sitemap_url || ''
      },
      pages: pagesR.rows,
      page_count: pagesR.rows.length
    });
  } catch(e) {
    console.error('[tracker-client GET]', e.message);
    res.status(500).json({ success: false, error: e.message });
  }
});

