// GET /api/admin/test-notify/:clientId — test email + Telegram for a client
app.get('/api/admin/test-notify/:clientId', verifyAdmin, async (req, res) => {
  try {
    const clientId = req.params.clientId;
    const cr = await pool.query('SELECT * FROM tracker_clients WHERE id=$1', [clientId]);
    if (!cr.rows.length) return res.json({ success: false, error: 'Client not found' });
    const c = cr.rows[0];

    const results = { email: null, telegram: null, client: { id: c.id, domain: c.domain, email: c.email, telegram_chat_id: c.telegram_chat_id } };

    // Test email
    if (c.email) {
      try {
        await sendTrackerEmail(clientId, 'Test notification — ContentScale Tracker',
          '<h3>Test notification</h3><p>This is a test email from your ContentScale AI Citations Tracker. If you received this, email notifications are working correctly.</p>');
        results.email = 'sent to ' + c.email;
      } catch(e) { results.email = 'ERROR: ' + e.message; }
    } else {
      results.email = 'no email on file';
    }

    // Test Telegram
    if (c.telegram_chat_id) {
      try {
        const ok = await sendTelegramNotification(c.telegram_chat_id, '✅ <b>Test notification</b> from ContentScale Tracker\n\nTelegram alerts are working for <b>' + c.domain + '</b>.');
        results.telegram = ok ? 'sent to chat ' + c.telegram_chat_id : 'failed';
      } catch(e) { results.telegram = 'ERROR: ' + e.message; }
    } else {
      results.telegram = 'no telegram_chat_id — client has not linked Telegram yet';
    }

    // Check Brevo key
    results.brevo_key = process.env.BREVO_API_KEY ? 'set (' + process.env.BREVO_API_KEY.substring(0,12) + '...)' : 'NOT SET';
    results.telegram_token = process.env.TELEGRAM_BOT_TOKEN ? 'set' : 'NOT SET';

    res.json({ success: true, results });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

app.get('/api/admin/test-engine-email', verifyAdmin, async (req, res) => {
  try {
    const sr = await pool.query("SELECT key,value FROM app_settings WHERE key IN ('engine_brief_emails','engine_from_email','engine_sender_name','contact_email')").catch(() => ({ rows: [] }));
    const m = {}; (sr.rows||[]).forEach(r => { m[r.key] = (r.value||'').trim(); });
    const recipients = (m.engine_brief_emails||'').split(',').map(e=>e.trim()).filter(e=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e));
    if (!recipients.length) return res.json({ success: false, error: 'No Engine Brief Emails configured \u2014 add your address in the field above and click Save first.' });
    const brevoKey = process.env.BREVO_API_KEY || '';
    if (!brevoKey) return res.json({ success: false, error: 'BREVO_API_KEY not set in Railway' });
    const from = m.engine_from_email || m.contact_email || process.env.FROM_EMAIL || 'info@contentscale.site';
    const name = m.engine_sender_name || 'ContentScale Engine';
    const resp = await fetch('https://api.brevo.com/v3/smtp/email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'api-key': brevoKey },
      body: JSON.stringify({
        to: recipients.map(e => ({ email: e })),
        sender: { email: from, name: name },
        subject: '[ENGINE] Test email \u2014 ContentScale Engine',
        htmlContent: '<div style="font-family:Verdana,sans-serif;max-width:560px;margin:0 auto;color:#0f172a;"><h2>\u2705 Engine email works</h2><p>This is a test from your ContentScale Content Engine settings. If you received this, your engine sender (' + name + ' &lt;' + from + '&gt;) and Brevo are configured correctly.</p><p style="font-size:12px;color:#64748b;">Sent to: ' + recipients.join(', ') + '</p></div>'
      })
    });
    if (!resp.ok) { const t = await resp.text().catch(()=>''); return res.json({ success: false, error: 'Brevo ' + resp.status + ' ' + t.slice(0,160) }); }
    res.json({ success: true, sent_to: recipients, from: from });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// GET /api/admin/brevo-status — check Brevo account: verified domains, quota, recent sends
app.get('/api/admin/brevo-status', verifyAdmin, async (req, res) => {
  try {
    const brevoKey = process.env.BREVO_API_KEY || '';
    if (!brevoKey) return res.json({ success: true, configured: false, reason: 'BREVO_API_KEY not set in Railway env vars' });

    const results = { configured: true, api_key_prefix: brevoKey.substring(0, 8) + '...', from_email: process.env.FROM_EMAIL || 'not set', sender_name: process.env.SENDER_NAME || 'not set', account: null, domains: [], recent_sends: [], quota: null, errors: [] };

    // 1. Account info (plan, quota)
    try {
      const accResp = await fetch('https://api.brevo.com/v3/account', { headers: { 'api-key': brevoKey, 'Accept': 'application/json' } });
      if (accResp.ok) {
        const acc = await accResp.json();
        var planStr = 'unknown';
        if (acc.plan) {
          if (Array.isArray(acc.plan)) planStr = acc.plan.map(function(p) { return p.type || JSON.stringify(p); }).join(', ');
          else if (typeof acc.plan === 'object') planStr = acc.plan.type || JSON.stringify(acc.plan);
          else planStr = String(acc.plan);
        }
        results.account = { email: acc.email, first_name: acc.firstName, last_name: acc.lastName, company: acc.companyName, plan: planStr };
        results.quota = acc.relay ? (acc.relay.daily_limit || acc.relay.quota || null) : null;
      } else {
        const errText = await accResp.text().catch(() => '');
        results.errors.push('Account API: HTTP ' + accResp.status + ' — ' + errText.substring(0, 200));
        if (accResp.status === 401) results.reason = 'Invalid BREVO_API_KEY (401 Unauthorized)';
      }
    } catch(e) { results.errors.push('Account fetch failed: ' + e.message); }

    // 2. Verified sender domains — try multiple endpoints + log raw for debug
    try {
      var domainRaw = null;
      var dResp1 = await fetch('https://api.brevo.com/v3/senders/domains', { headers: { 'api-key': brevoKey, 'Accept': 'application/json' } });
      if (dResp1.ok) {
        domainRaw = await dResp1.json();
      } else if (dResp1.status === 404) {
        var dResp2 = await fetch('https://api.brevo.com/v3/senders', { headers: { 'api-key': brevoKey, 'Accept': 'application/json' } });
        if (dResp2.ok) domainRaw = await dResp2.json();
      }
      if (domainRaw) {
        results._domainsRaw = JSON.stringify(domainRaw).substring(0, 500);
        var domainArr = [];
        if (Array.isArray(domainRaw)) domainArr = domainRaw;
        else if (domainRaw.domains && Array.isArray(domainRaw.domains)) domainArr = domainRaw.domains;
        else if (domainRaw.senders && Array.isArray(domainRaw.senders)) domainArr = domainRaw.senders;
        results.domains = domainArr.map(function(d) { return { domain: d.domain || d.domain_name || d.name || d.email || '(unknown)', verified: !!(d.verified || d.isVerified), authenticated: !!(d.authenticated || d.isAuthenticated) }; });
      } else {
        results.errors.push('Domains API: HTTP ' + dResp1.status);
      }
    } catch(e) { results.errors.push('Domains fetch failed: ' + e.message); }

    // 3. Recent transactional sends — use aggregate stats (more reliable than events)
    try {
      var sResp = await fetch('https://api.brevo.com/v3/smtp/statistics/aggregatedReport', { headers: { 'api-key': brevoKey, 'Accept': 'application/json' } });
      if (sResp.ok) {
        var sData = await sResp.json();
        var gs = sData.globalStats || {};
        results.recent_summary = { total: gs.sent || 0, delivered: gs.delivered || 0, bounced: gs.bounced || 0, blocked: gs.blocked || 0, spam: gs.spam || 0, opens: gs.opens || 0, clicks: gs.clicks || 0 };
      } else {
        results.errors.push('Stats API: HTTP ' + sResp.status);
      }
    } catch(e) { results.errors.push('Stats fetch failed: ' + e.message); }

    // 4. Check if FROM_EMAIL domain matches a verified domain
    const fromDomain = (process.env.FROM_EMAIL || '').split('@')[1];
    if (fromDomain && results.domains.length) {
      const matched = results.domains.find(function(d) { return d.domain === fromDomain && d.verified; });
      results.from_domain_verified = !!matched;
      results.from_domain = fromDomain;
      if (!matched) results.errors.push('Sender domain "' + fromDomain + '" is NOT verified in Brevo. Emails will be silently dropped.');
    }

    res.json({ success: true, results });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

