// POST /api/admin/tracker-clients/:id/regenerate-token
app.post('/api/admin/tracker-clients/:id/regenerate-token', verifyAdmin, async (req, res) => {
  try {
    const newToken = require('crypto').randomBytes(24).toString('hex');
    await pool.query('UPDATE tracker_clients SET token=$1 WHERE id=$2', [newToken, req.params.id]);
    const appUrl = process.env.APP_URL || 'https://app.contentscale.site';
    const newUrl = appUrl + '/track/' + newToken;

    // Get client info to resend email
    const cr = await pool.query('SELECT * FROM tracker_clients WHERE id=$1', [req.params.id]);
    const client = cr.rows[0];
    if (client && client.email) {
      const html = '<h2 style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:10px;">Your tracker link has been updated</h2>'
        + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">Your previous link has been deactivated. Here is your new personal tracker link for <strong>' + client.domain + '</strong>:</p>'
        + '<div style="background:#f5f3ff;border:1px solid #ddd6fe;border-radius:8px;padding:14px 16px;margin-bottom:16px;">'
        + '<div style="font-size:11px;font-family:monospace;color:#7c3aed;word-break:break-all;margin-bottom:10px;">' + newUrl + '</div>'
        + '<a href="' + newUrl + '" style="display:inline-block;background:#7c3aed;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">Open tracker &rarr;</a>'
        + '</div>'
        + '<p style="font-size:13px;color:#374151;">All your pages, scans, and Citation Briefs are still there — nothing was lost. Bookmark this new link.</p>';
      await sendTrackerEmail(client.id, 'Your tracker link has been updated — ' + client.domain, html).catch(()=>{});
    }
    res.json({ success: true, new_url: newUrl, token: newToken });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// POST /api/admin/tracker-clients/:id/email-last-brief — manually (re)send the most recent Citation Brief by email
app.post('/api/admin/tracker-clients/:id/email-last-brief', verifyAdmin, async (req, res) => {
  try {
    const cr = await pool.query('SELECT * FROM tracker_clients WHERE id=$1', [req.params.id]);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Client not found' });
    const client = cr.rows[0];
    if (!client.email) return res.status(400).json({ success: false, error: 'Client has no email address on file' });
    const pr = await pool.query(
      `SELECT url, brief_content FROM tracker_pages
       WHERE tracker_client_id=$1 AND brief_content IS NOT NULL AND (is_active=TRUE OR is_active IS NULL)
       ORDER BY brief_started_at DESC NULLS LAST, id DESC LIMIT 1`,
      [client.id]
    );
    if (!pr.rows.length) return res.status(400).json({ success: false, error: 'No brief found yet for this client — run a scan first' });
    const page = pr.rows[0];
    let brief; try { brief = typeof page.brief_content === 'string' ? JSON.parse(page.brief_content) : page.brief_content; } catch(e) { brief = null; }
    const items = (brief && Array.isArray(brief.items)) ? brief.items : [];
    if (!items.length) return res.status(400).json({ success: false, error: 'Latest brief has no recommendations to send' });
    const _esc = s => String(s==null?'':s).replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]));
    const recHtml = items.map(it => {
      const t = it.h2 || it.title || it.heading || it.action || 'Recommendation';
      const b = it.body || it.content || it.text || it.detail || '';
      const w = it.reason || it.why || it.impact || it.rationale || '';
      return '<div style="border-left:3px solid #7c3aed;padding:4px 0 4px 14px;margin-bottom:18px;">'
        + '<div style="font-size:14px;font-weight:800;color:#0f172a;margin-bottom:6px;">' + _esc(t) + '</div>'
        + (b ? '<div style="font-size:13px;color:#374151;line-height:1.65;">' + _esc(b) + '</div>' : '')
        + (w ? '<div style="font-size:12px;color:#7c3aed;font-style:italic;margin-top:6px;line-height:1.5;">' + _esc(w) + '</div>' : '')
        + '</div>';
    }).join('');
    const html = '<div style="font-size:13px;color:#64748b;margin-bottom:6px;">AI Citation Brief</div>'
      + '<div style="font-size:16px;font-weight:800;color:#0f172a;margin-bottom:16px;word-break:break-all;">' + _esc(page.url) + '</div>'
      + recHtml;
    await notifyClient(client.id, 'Your AI Citation Brief — ' + client.domain, html, '\u{1F3AF} Your AI Citation Brief for ' + page.url);
    res.json({ success: true, message: 'Brief emailed to ' + client.email });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// POST /api/admin/tracker-clients/create-own — admin creates tracker for paying client
app.post('/api/admin/tracker-clients/create-own', verifyAdmin, async (req, res) => {
  try {
    const { domain, name, email, max_pages, source } = req.body;
    if (!domain) return res.status(400).json({ success: false, error: 'Domain required' });
    const cleanDomain = domain.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase().trim();

    // Check existing
    const existing = await pool.query('SELECT id, token FROM tracker_clients WHERE domain=$1 AND status != $2', [cleanDomain, 'deleted']);
    if (existing.rows.length) {
      const existingUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + existing.rows[0].token;
      return res.json({ success: true, token: existing.rows[0].token, url: existingUrl, existing: true });
    }

    const token = generateClientToken();
    const maxPg = parseInt(max_pages) || 10;
    // Plan rule: free = 3 pages -> GSC off; any paid tier (>3 pages) -> GSC on automatically.
    await pool.query(
      `INSERT INTO tracker_clients (token, domain, name, email, max_pages, status, gsc_enabled) VALUES ($1,$2,$3,$4,$5,'active',$6)`,
      [token, cleanDomain, name||null, email||null, maxPg, maxPg > 3]
    );

    const trackUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + token;

    // Send welcome email
    if (email) {
      const clientId = (await pool.query('SELECT id FROM tracker_clients WHERE token=$1', [token])).rows[0]?.id;
      const _roToken = clientId ? await ensureReadonlyToken(clientId) : null; // RO link exists from day one
      if (clientId) {
        const welcomeHtml = '<h2 style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:10px;">Your AI Citations Tracker is ready</h2>'
          + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:6px;">Hi ' + (name||'there') + ',<br><br>Your personal tracker for <strong>' + cleanDomain + '</strong> has been set up. You have two links \u2014 bookmark the first, share the second:</p>'
          + emailLinkBlock(token, _roToken)
          + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;"><strong>What happens next:</strong><br>'
          + '1. Add your pages and keywords<br>2. First scan runs in ~1 minute<br>3. Paste your page HTML for GRAAF score<br>4. Citation Brief arrives by email</p>'
          + '<p style="font-size:13px;color:#374151;">Questions? WhatsApp Ottmar: <a href="https://wa.me/31628073996" style="color:#7c3aed;">wa.me/31628073996</a></p>';
        await sendTrackerEmail(clientId, 'Your AI Citations Tracker is ready — ' + cleanDomain, welcomeHtml).catch(()=>{});
      }
    }

    // Notify Ottmar — email + Telegram (CallMeBot free tier is unreliable, replaced 2026-07-22)
    notifyOttmar(
      '⭐ New tracker client: ' + cleanDomain,
      '<p><strong>New own-client tracker created.</strong></p><p>Domain: ' + cleanDomain + '<br>Name: ' + (name || 'anon') + '<br>Pages: ' + maxPg + '</p><p><a href="' + trackUrl + '">' + trackUrl + '</a></p>',
      'Domain: ' + cleanDomain + ' | Name: ' + (name || 'anon') + ' | Pages: ' + maxPg + '\n' + trackUrl
    ).catch(() => {});

    res.json({ success: true, token, url: trackUrl });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

