app.post('/api/engine/brief-email', verifyEngineAccess, async (req, res) => {
  try {
    if (!pool) return res.json({ success: false, error: 'No DB' });
    const brief = ((req.body && req.body.brief) || '').toString();
    if (!brief.trim()) return res.json({ success: false, error: 'No brief' });
    const url = ((req.body && req.body.url) || '').toString().slice(0, 300);
    const keyword = ((req.body && req.body.keyword) || '').toString().slice(0, 160);
    const _kind = (req.body && req.body.kind) || 'brief';
    const _lbl = _kind === 'summary' ? 'Rewrite Summary' : _kind === 'rewrite' ? 'Rewritten HTML (ready to edit)' : 'Master Brief';
    const sr = await pool.query("SELECT key,value FROM app_settings WHERE key IN ('engine_brief_emails','engine_from_email','engine_sender_name')").catch(() => ({ rows: [] }));
    const _em = {}; (sr.rows||[]).forEach(r => { _em[r.key] = (r.value||'').trim(); });
        const raw = (_em.engine_brief_emails || '');
        const _engFrom = _em.engine_from_email || process.env.FROM_EMAIL || 'info@contentscale.site';
        const _engName = _em.engine_sender_name || 'ContentScale Engine';
    const _toOverride = ((req.body && req.body.to) || '').toString();
    const _rxEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const _parseEmails = str => Array.from(new Set(String(str||'').split(/[,;\n]+/).map(e => e.trim()).filter(e => _rxEmail.test(e))));
    let recipients = _parseEmails(raw);
    _parseEmails(_toOverride).forEach(function(e){ if (recipients.indexOf(e) < 0) recipients.push(e); });
    if (!recipients.length) return res.json({ success: false, error: 'No recipient - add team emails in admin (engine_brief_emails) and/or pick a specialist in the Send-brief-to field.' });
    const brevoKey = process.env.BREVO_API_KEY || '';
    if (!brevoKey) return res.json({ success: false, error: 'No BREVO_API_KEY' });
    const eu = req.engineUser || {};
    let who = eu.client_name || eu.clientName || eu.domain || eu.code;
    if (who && typeof who === 'object') who = who.client_name || who.name || who.domain || who.code || '';
    if (typeof who !== 'string' || !who.trim()) who = eu.isAdmin ? 'admin' : 'engine user';
    const esc = x => String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const htmlBody = '<div style="font-family:Verdana,Geneva,sans-serif;max-width:680px;margin:0 auto;color:#0f172a;">'
      + '<div style="background:#0f172a;border-radius:10px 10px 0 0;padding:18px 24px;color:#fff;font-weight:800;">ContentScale Engine \u2014 ' + _lbl + '</div>'
      + '<div style="background:#fff;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 10px 10px;padding:22px 24px;">'
      + '<p style="font-size:13px;color:#475569;margin:0 0 12px;">Sent by <strong>ContentScale.site</strong> \u2014 Made for <strong>' + esc(url ? String(url).replace(/^https?:\/\//,'').replace(/\/+$/,'') : who) + '</strong></p>'
      + ((url || keyword) ? '<p style="font-size:12px;color:#94a3b8;margin:0 0 12px;">' + (url ? 'Page: <strong style="color:#475569;">' + esc(url) + '</strong>' : '') + (url && keyword ? ' \u00b7 ' : '') + (keyword ? 'Keyword: <strong style="color:#475569;">' + esc(keyword) + '</strong>' : '') + '</p>' : '')
      + '<pre style="white-space:pre-wrap;word-break:break-word;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:14px;font-size:12px;line-height:1.55;color:#1e293b;font-family:Consolas,monospace;">' + esc(brief) + '</pre>'
      + '</div></div>';
    const resp = await fetch('https://api.brevo.com/v3/smtp/email', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'api-key': brevoKey },
      body: JSON.stringify({
        to: recipients.map(e => ({ email: e })),
        sender: { email: _engFrom, name: _engName },
        subject: '[ENGINE] ' + _lbl + (keyword ? ' \u2014 ' + keyword : '') + (url ? ' \u2014 ' + url.replace(/^https?:\/\//,'').replace(/\/$/,'') : ''),
        htmlContent: htmlBody
      })
    });
    if (!resp.ok) { const t = await resp.text().catch(() => ''); return res.json({ success: false, error: 'Brevo ' + resp.status + ' ' + t.slice(0, 160) }); }
    res.json({ success: true, sent_to: recipients.length });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

