// GET /api/admin/tracker-clients/debug-pages — show all clients with domain/pages status
app.get('/api/admin/tracker-clients/debug-pages', verifyAdmin, async (req, res) => {
  try {
    const clients = await pool.query(`
      SELECT tc.id, tc.domain, tc.extra_domains, tc.max_pages, tc.dealify_codes,
             COUNT(tp.id) as actual_pages
      FROM tracker_clients tc
      LEFT JOIN tracker_pages tp ON tp.tracker_client_id = tc.id AND (tp.is_active=TRUE OR tp.is_active IS NULL)
      WHERE tc.status != 'deleted'
      GROUP BY tc.id
      ORDER BY tc.domain
    `);

    const report = clients.rows.map(c => {
      const extraList = (c.extra_domains||'').split(',').map(d => d.trim()).filter(Boolean);
      const domainCount = 1 + extraList.length;
      const dealifyCount = c.dealify_codes ? c.dealify_codes.split(',').filter(x => x.trim()).length : 0;
      const basePerDomain = dealifyCount > 0 ? dealifyCount * 10 : 3;
      const correctMax = domainCount * basePerDomain;
      const isWrong = c.max_pages !== correctMax;
      return {
        domain: c.domain,
        extra_domains: c.extra_domains || 'none',
        domain_count: domainCount,
        base_per_domain: basePerDomain,
        current_max_pages: c.max_pages,
        correct_max_pages: correctMax,
        actual_pages_tracked: parseInt(c.actual_pages),
        status: isWrong ? '❌ WRONG — should be ' + correctMax : '✅ OK',
        dealify: dealifyCount > 0 ? dealifyCount + ' codes' : 'none'
      };
    });

    const wrongCount = report.filter(r => r.status.startsWith('❌')).length;
    res.json({
      success: true,
      summary: wrongCount + ' clients need fixing out of ' + report.length + ' total',
      clients: report
    });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// POST /api/admin/tracker-clients/recalc-max-pages — fix max_pages for all clients with extra_domains
app.post('/api/admin/tracker-clients/recalc-max-pages', verifyAdmin, async (req, res) => {
  try {
    const clients = await pool.query('SELECT id, domain, extra_domains, max_pages, dealify_codes FROM tracker_clients WHERE status != $1', ['deleted']);
    let fixed = 0;
    for (const c of clients.rows) {
      if (!c.extra_domains || !c.extra_domains.trim()) continue;
      const extraList = c.extra_domains.split(',').map(d => d.trim()).filter(Boolean);
      const domainCount = 1 + extraList.length;
      // Determine base pages per domain
      const dealifyCount = c.dealify_codes ? c.dealify_codes.split(',').filter(x => x.trim()).length : 0;
      const basePerDomain = dealifyCount > 0 ? dealifyCount * 10 : 3;
      const correctMax = domainCount * basePerDomain;
      if ((c.max_pages || 0) < correctMax) { // only raise — a manually increased limit (e.g. 100) is sacred
        await pool.query('UPDATE tracker_clients SET max_pages=$1 WHERE id=$2', [correctMax, c.id]);
        console.log(`[recalc] ${c.domain}: ${c.max_pages} → ${correctMax} (${domainCount} domains × ${basePerDomain})`);
        fixed++;
      }
    }
    res.json({ success: true, fixed, total: clients.rows.length });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// POST /api/admin/tracker-clients/:id/clean-pages — remove image/asset URLs + merge duplicates
app.post('/api/admin/tracker-clients/:id/clean-pages', verifyAdmin, async (req, res) => {
  try {
    const clientId = req.params.id;

    // 1. Remove non-content pages (images, assets, feeds, etc)
    const badExtensions = ['.jpg','.jpeg','.png','.gif','.webp','.svg','.ico','.pdf','.zip','.mp4','.mp3','.css','.js','.woff','.woff2','.ttf','.eot','.xml','.json','.txt','.csv'];
    const badPatterns = ['wp-content/uploads','wp-includes','/feed/','/feed','/amp/','/amp','?replytocom=','#','wp-json'];

    const pages = await pool.query('SELECT id, url FROM tracker_pages WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL)', [clientId]);
    let cleaned = 0;
    let merged = 0;

    for (const p of pages.rows) {
      const url = (p.url || '').toLowerCase();
      const isBadExt = badExtensions.some(ext => url.split('?')[0].endsWith(ext));
      const isBadPattern = badPatterns.some(pat => url.includes(pat));
      if (isBadExt || isBadPattern) {
        await pool.query('UPDATE tracker_pages SET is_active=FALSE WHERE id=$1', [p.id]);
        cleaned++;
      }
    }

    // 2. Merge duplicate URLs — keep the one with best data
    const activePagesR = await pool.query(`
      SELECT id, url, keyword, last_checked, google_position, brief_check_count, graaf_score
      FROM tracker_pages
      WHERE tracker_client_id=$1 AND is_active=TRUE
      ORDER BY url, COALESCE(google_position, 999) ASC, brief_check_count DESC NULLS LAST
    `, [clientId]);

    const seen = {};
    for (const p of activePagesR.rows) {
      const normalUrl = p.url.replace(/^https?:\/\/(www\.)?/, '').replace(/\/$/, '').toLowerCase();
      if (seen[normalUrl]) {
        // Duplicate — keep the first (best) one, disable this
        await pool.query('UPDATE tracker_pages SET is_active=FALSE WHERE id=$1', [p.id]);
        merged++;
      } else {
        seen[normalUrl] = p.id;
      }
    }

    res.json({ success: true, cleaned, merged, total: pages.rows.length });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// POST /api/admin/tracker-clients/merge-duplicates
app.post('/api/admin/tracker-clients/merge-duplicates', verifyAdmin, async (req, res) => {
  try {
    // Find all domains that appear more than once (normalised: strip www)
    const dupes = await pool.query(`
      SELECT LOWER(REGEXP_REPLACE(domain, '^www\\.', '')) as base_domain, 
             array_agg(id ORDER BY created_at ASC) as ids,
             COUNT(*) as cnt
      FROM tracker_clients
      WHERE status != 'deleted'
      GROUP BY LOWER(REGEXP_REPLACE(domain, '^www\\.', ''))
      HAVING COUNT(*) > 1
    `);

    let mergedCount = 0;
    const details = [];

    for (const row of dupes.rows) {
      const ids = row.ids; // sorted oldest first
      const keepId = ids[0]; // keep oldest
      const removeIds = ids.slice(1); // remove newer duplicates

      // Move all pages from duplicate accounts to the keeper
      for (const dupId of removeIds) {
        await pool.query('UPDATE tracker_pages SET tracker_client_id=$1 WHERE tracker_client_id=$2', [keepId, dupId]);
        // Copy email/whatsapp if keeper has none
        const dupClient = await pool.query('SELECT email, whatsapp, name, max_pages FROM tracker_clients WHERE id=$1', [dupId]);
        const keepClient = await pool.query('SELECT email, whatsapp, name, max_pages FROM tracker_clients WHERE id=$1', [keepId]);
        const dup = dupClient.rows[0]; const keep = keepClient.rows[0];
        const updates = [];
        if (!keep.email && dup.email) updates.push(`email='${dup.email.replace(/'/g,"''")}'`);
        if (!keep.whatsapp && dup.whatsapp) updates.push(`whatsapp='${dup.whatsapp.replace(/'/g,"''")}'`);
        if (!keep.name && dup.name) updates.push(`name='${dup.name.replace(/'/g,"''")}'`);
        const newMax = Math.max(keep.max_pages || 3, dup.max_pages || 3);
        updates.push(`max_pages=${newMax}`);
        if (updates.length) await pool.query(`UPDATE tracker_clients SET ${updates.join(',')} WHERE id=$1`, [keepId]);
        // Mark duplicate as deleted
        await pool.query("UPDATE tracker_clients SET status='deleted' WHERE id=$1", [dupId]);
        mergedCount++;
      }
      details.push(row.base_domain + ' (' + ids.length + ' → 1)');
    }

    res.json({ success: true, merged: mergedCount, details: details.join(', ') || 'No duplicates found' });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// PATCH /api/admin/tracker-clients/:id/frequency — change frequency for all client pages
app.patch('/api/admin/tracker-clients/:id/frequency', verifyAdmin, async (req, res) => {
  try {
    const { frequency } = req.body;
    const allowed = ['0','0days','off','1day','3days','7days','17days','21days','30days','weekly','1week','2weeks','monthly'];
    if (!allowed.includes(frequency)) return res.status(400).json({ success: false, error: 'Invalid frequency' });
    const _off = (frequency==='0'||frequency==='0days'||frequency==='off');
    if (_off) {
      await pool.query(
        `UPDATE tracker_pages SET check_frequency='0', next_check_at=NULL
           WHERE tracker_client_id=$1 AND (is_active=TRUE OR is_active IS NULL)`,
        [req.params.id]
      );
      return res.json({ success: true, frequency: '0', days: 0 });
    }
    const _fm = { 'daily':1,'1day':1,'3days':3,'7days':7,'weekly':7,'1week':7,'2weeks':14,'17days':17,'21days':21,'30days':30,'monthly':30 };
    let _d = _fm[frequency]; if (!_d) { const _m = String(frequency).match(/^(\d+)\s*days?$/); _d = _m ? parseInt(_m[1],10) : 3; }
    await pool.query(
      `UPDATE tracker_pages
         SET check_frequency=$1,
             next_check_at = COALESCE(last_checked_at, NOW()) + INTERVAL '${_d} days'
       WHERE tracker_client_id=$2 AND (is_active=TRUE OR is_active IS NULL)`,
      [frequency, req.params.id]
    );
    res.json({ success: true, frequency, days: _d });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// PATCH /api/admin/tracker-pages/:pageId/frequency — set scan interval for ONE page (3/7/17/21/30 days)
app.patch('/api/admin/tracker-pages/:pageId/frequency', verifyAdmin, async (req, res) => {
  try {
    const { frequency } = req.body;
    const allowed = ['0','0days','off','1day','3days','7days','17days','21days','30days','weekly','1week','2weeks','monthly'];
    if (!allowed.includes(frequency)) return res.status(400).json({ success: false, error: 'Invalid frequency' });
    const _off = (frequency==='0'||frequency==='0days'||frequency==='off');
    if (_off) {
      await pool.query(`UPDATE tracker_pages SET check_frequency='0', next_check_at=NULL WHERE id=$1`, [req.params.pageId]);
      return res.json({ success: true, frequency: '0', days: 0 });
    }
    const _fm = { 'daily':1,'1day':1,'3days':3,'7days':7,'weekly':7,'1week':7,'2weeks':14,'17days':17,'21days':21,'30days':30,'monthly':30 };
    let _d = _fm[frequency]; if (!_d) { const _m = String(frequency).match(/^(\d+)\s*days?$/); _d = _m ? parseInt(_m[1],10) : 3; }
    // Save interval AND re-anchor next_check_at from the last scan (or now) so the scan + its
    // notification email fire on the correct new date for this specific page.
    await pool.query(
      `UPDATE tracker_pages
         SET check_frequency=$1,
             next_check_at = COALESCE(last_checked_at, NOW()) + INTERVAL '${_d} days'
       WHERE id=$2`,
      [frequency, req.params.pageId]
    );
    res.json({ success: true, frequency, days: _d });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

// GET /api/admin/tracker-clients/:id — single client (defensive; prevents 404 if any UI/link fetches one client directly)
app.get('/api/admin/tracker-clients/:id', verifyAdmin, async (req, res) => {
  try {
    if (!/^\d+$/.test(req.params.id)) return res.status(404).json({ success: false, error: 'Not found' });
    const r = await pool.query('SELECT * FROM tracker_clients WHERE id=$1', [req.params.id]);
    if (!r.rows.length) return res.status(404).json({ success: false, error: 'Client not found' });
    res.json({ success: true, client: r.rows[0] });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});
// POST /api/admin/tracker-clients/:id/readonly-link — create (or return existing) live read-only share link.
// The owner keeps working on the main token; this second token shows the SAME live data, view-only.
app.post('/api/admin/tracker-clients/:id/readonly-link', verifyAdmin, async (req, res) => {
  try {
    const r = await pool.query('SELECT readonly_token FROM tracker_clients WHERE id=$1', [req.params.id]);
    if (!r.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    let roToken = r.rows[0].readonly_token;
    if (req.body && req.body.regenerate) roToken = null; // rotate: old shared links stop working
    if (!roToken) {
      roToken = 'ro_' + generateClientToken();
      await pool.query('UPDATE tracker_clients SET readonly_token=$1 WHERE id=$2', [roToken, req.params.id]);
    }
    res.json({ success: true, readonly_token: roToken, url: 'https://app.contentscale.site/track/' + roToken });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

app.patch('/api/admin/tracker-clients/:id', verifyAdmin, async (req, res) => {
  try {
    const { max_pages, status, reset_ip } = req.body;
    const updates = []; const vals = []; let i = 1;
    if (max_pages !== undefined) { updates.push(`max_pages=$${i++}`); vals.push(max_pages); }
    if (req.body.prewrite_briefs_paid !== undefined) { updates.push(`prewrite_briefs_paid=$${i++}`); vals.push(parseInt(req.body.prewrite_briefs_paid) || 0); }
    if (req.body.extra_domains !== undefined) {
      updates.push(`extra_domains=$${i++}`);
      vals.push(req.body.extra_domains || '');
      // Auto-calculate max_pages: 3 per domain (1 primary + extra domains)
      // Only auto-update if max_pages not explicitly set in this request
      if (max_pages === undefined) {
        const extraList = (req.body.extra_domains || '').split(',').map(d => d.trim()).filter(Boolean);
        const domainCount = 1 + extraList.length; // primary + extras
        // Get current base max_pages to preserve Dealify stacking
        const curR = await pool.query('SELECT max_pages, dealify_codes FROM tracker_clients WHERE id=$1', [req.params.id]);
        if (curR.rows.length) {
          const cur = curR.rows[0];
          const dealifyBonus = cur.dealify_codes ? (cur.dealify_codes.split(',').filter(c => c.trim()).length * 10) : 0;
          const basePages = dealifyBonus > 0 ? dealifyBonus : 3; // Dealify clients get 10/code, free clients get 3
          // Never LOWER a manually raised limit — auto-calc may only raise (fixes: admin sets 100, a later
          // extra_domains save silently reset it to domains×base)
          const newMax = Math.max(domainCount * basePages, cur.max_pages || 0);
          updates.push(`max_pages=$${i++}`);
          vals.push(newMax);
          console.log(`[admin] Auto-updated max_pages: ${domainCount} domains × ${basePages} → ${newMax} (never lowered)`);
        }
      }
    }
    if (req.body.gsc_enabled !== undefined) { updates.push(`gsc_enabled=$${i++}`); vals.push(!!req.body.gsc_enabled); }
    if (req.body.demo_readonly !== undefined) { updates.push(`demo_readonly=$${i++}`); vals.push(!!req.body.demo_readonly); }
    else if (max_pages !== undefined) {
      // Plan changed without an explicit GSC choice -> follow the plan rule automatically (free ≤3 off, paid >3 on)
      updates.push(`gsc_enabled=$${i++}`); vals.push(parseInt(max_pages) > 3);
      console.log('[admin] gsc_enabled auto-set to', parseInt(max_pages) > 3, 'from max_pages', max_pages);
    }
    if (req.body.cc_emails !== undefined) { updates.push(`cc_emails=$${i++}`); vals.push(req.body.cc_emails || ''); }
    if (req.body.lead_name !== undefined) { updates.push(`lead_name=$${i++}`); vals.push(req.body.lead_name || ''); }
    if (req.body.lead_email !== undefined) { updates.push(`lead_email=$${i++}`); vals.push(req.body.lead_email || ''); }
    if (status !== undefined) {
      updates.push(`status=$${i++}`);
      vals.push(status);
      if (status === 'active') { updates.push(`paused_at=NULL`); }
    }
    if (reset_ip) { updates.push(`registered_ip=NULL`); }
    if (!updates.length) return res.status(400).json({ success: false, error: 'Nothing to update' });
    // Detect a newly-set / changed lead email so we can welcome the lead with both links
    let _leadJustSet = false;
    if (req.body.lead_email !== undefined) {
      const _nl = String(req.body.lead_email || '').trim();
      if (_nl) {
        try {
          const _pr = await pool.query('SELECT lead_email FROM tracker_clients WHERE id=$1', [req.params.id]);
          const _prev = _pr.rows[0] ? String(_pr.rows[0].lead_email || '').trim() : '';
          if (_nl.toLowerCase() !== _prev.toLowerCase()) _leadJustSet = true;
        } catch(e) {}
      }
    }
    vals.push(req.params.id);
    await pool.query(`UPDATE tracker_clients SET ${updates.join(',')} WHERE id=$${i}`, vals);
    if (_leadJustSet) _sendLeadWelcome(req.params.id).catch(()=>{});
    res.json({ success: true });
  } catch(e) { res.status(500).json({ success: false, error: e.message }); }
});

