// ============================================
// 🗺️ SITEMAP SCANNER ENDPOINTS
// ============================================
// Fetch and parse sitemap → return URL list
app.post('/api/sitemap/urls', async (req, res) => {
const { url } = req.body;
if (!url) return res.status(400).json({ success: false, error: 'Sitemap URL required' });
try {
// No xml2js needed — parse <loc> tags with regex (works for all standard sitemaps)
const extractLocs = (xml) => {
const locs = [];
const re = /<loc>\s*(https?:\/\/[^<\s]+)\s*<\/loc>/gi;
let m;
while ((m = re.exec(xml)) !== null) locs.push(m[1].trim());
return locs;
};
const fetchXml = async (sitemapUrl) => {
const resp = await axios.get(sitemapUrl, { timeout: 15000, headers: { 'User-Agent': 'ContentScaleBot/1.0' }, responseType: 'text' });
return resp.data;
};
const xml = await fetchXml(url);
let urls = [];
// Sitemap index — contains sub-sitemap URLs
if (xml.includes('<sitemapindex')) {
const subSitemapUrls = extractLocs(xml);
for (const smUrl of subSitemapUrls.slice(0, 10)) {
try {
const subXml = await fetchXml(smUrl);
urls.push(...extractLocs(subXml));
} catch(e) { /* skip broken sub-sitemap */ }
}
} else {
// Regular urlset
urls = extractLocs(xml);
}
// Deduplicate + filter out non-page URLs
const filtered = [...new Set(urls)].filter(u => {
const skip = ['/tag/', '/category/', '/author/', '/feed/', '?', '#', '.xml', '.pdf', '.jpg', '.png'];
return !skip.some(s => u.includes(s));
});
res.json({ success: true, urls: filtered, total: filtered.length });
} catch (e) {
res.status(500).json({ success: false, error: 'Could not fetch sitemap: ' + e.message });
}
});
// ============================================================
// /api/fetch-html
// Fetches raw HTML of any URL via axios (fast) with Puppeteer fallback.
// Used by PULSE+NEXUS to auto-fill ③ Your Page HTML field.
// POST body: { url: "https://example.com/page" }
// Returns:   { success: true, html: "...", url: "...", method: "axios"|"puppeteer" }
// ============================================================
app.post('/api/fetch-html', async (req, res) => {
  const { url } = req.body;
  if (!url) return res.status(400).json({ success: false, error: 'url required' });
  let fetchUrl = url.startsWith('http') ? url : 'https://' + url;

  // ── Attempt 1: axios — fast, no browser needed ──────────
  try {
    const r = await axios.get(fetchUrl, {
      timeout: 12000,
      maxRedirects: 5,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'en-US,en;q=0.9',
        'Cache-Control': 'no-cache',
      },
      responseType: 'text',
    });
    const html = r.data;
    if (html && html.length > 500 && (html.includes('<html') || html.includes('<!DOCTYPE'))) {
      console.log(`[fetch-html] axios OK: ${fetchUrl} (${html.length} chars)`);
      return res.json({ success: true, html, url: fetchUrl, method: 'axios' });
    }
    console.log(`[fetch-html] axios thin response (${html.length} chars) — trying Puppeteer`);
  } catch (axiosErr) {
    console.log(`[fetch-html] axios failed (${axiosErr.message}) — trying Puppeteer`);
  }

  // ── Attempt 2: Puppeteer — handles JS-rendered pages ────
  let page = null;
  try {
    let browser = await getBrowser();
    if (!browser) { browserInstance = null; browser = await getBrowser(); }
    if (!browser) return res.status(503).json({ success: false, error: 'Browser unavailable — try again in 10 seconds or paste HTML manually' });

    page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 900 });
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');

    // Block images/fonts/media — only need HTML
    await page.setRequestInterception(true);
    page.on('request', (interceptedReq) => {
      const type = interceptedReq.resourceType();
      if (['image', 'media', 'font', 'stylesheet'].includes(type)) interceptedReq.abort();
      else interceptedReq.continue();
    });

    await page.goto(fetchUrl, { waitUntil: 'domcontentloaded', timeout: 20000 });
    await new Promise(r => setTimeout(r, 1500));
    const html = await page.evaluate(() => document.documentElement.outerHTML);

    if (!html || html.length < 500) {
      return res.status(422).json({ success: false, error: 'Page returned empty HTML — site may be blocking bots. Paste HTML manually.' });
    }
    console.log(`[fetch-html] Puppeteer OK: ${fetchUrl} (${html.length} chars)`);
    return res.json({ success: true, html, url: fetchUrl, method: 'puppeteer' });
  } catch (e) {
    console.error(`[fetch-html] Puppeteer error: ${e.message}`);
    return res.status(502).json({ success: false, error: 'Could not fetch page: ' + e.message + ' — paste HTML manually in ③' });
  } finally {
    if (page) { try { await page.close(); } catch (_) {} }
  }
});


// ============================================================
// /api/scan/paste
// Scans pasted HTML directly — no URL fetch, no Puppeteer needed.
// POST body: { html: "...", url: "https://example.com" (optional label) }
// ============================================================
app.post('/api/scan/paste', async (req, res) => {
  const { html, url: labelUrl } = req.body;
  if (!html || html.length < 100) {
    return res.status(400).json({ success: false, error: 'HTML too short or missing' });
  }

  try {
    // Create a virtual DOM analysis using the same scoring logic
    // We simulate what the browser evaluate() returns
    const scanUrl = labelUrl || 'pasted-html';

    // Parse HTML with cheerio-like regex (fast, no extra dependency)
    const rawHtml = html;
    const textMatch = rawHtml.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
    const bodyHtml = textMatch ? textMatch[1] : rawHtml;

    // Strip tags to get text content
    const stripTags = (str) => str.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    const cleanText = stripTags(bodyHtml);
    const wordCount = cleanText.split(/\s+/).filter(w => w.length > 0).length;

    // Count headings
    const h1Matches = [...rawHtml.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)];
    const h1Count = h1Matches.length;
    const h1Text = h1Matches[0] ? stripTags(h1Matches[0][1]) : '';
    const h1Length = h1Text.length;
    const h1IsGeneric = h1Text.length > 0 && ['welcome','home','hello','untitled','page','index','main','default'].includes(h1Text.toLowerCase().trim());
    const h1IsTooShort = h1Text.length > 0 && h1Text.length < 10;
    const h1IsTooLong = h1Text.length > 70;

    const h2Count = ([...rawHtml.matchAll(/<h2/gi)]).length;
    const h3Count = ([...rawHtml.matchAll(/<h3/gi)]).length;
    const listItemCount = ([...rawHtml.matchAll(/<li/gi)]).length;

    // Paragraph stats
    const pMatches = [...rawHtml.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)];
    const avgParagraphLength = pMatches.length > 0 
      ? pMatches.map(m => stripTags(m[1]).split(/\s+/).length).reduce((a,b) => a+b, 0) / pMatches.length 
      : 0;

    // Meta
    const titleMatch = rawHtml.match(/<title>([^<]+)<\/title>/i);
    const metaTitle = titleMatch ? titleMatch[1] : '';
    const metaTitleLength = metaTitle.length;

    const descMatch = rawHtml.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i) 
      || rawHtml.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']description["']/i);
    const metaDescription = descMatch ? descMatch[1] : '';
    const metaDescriptionLength = metaDescription.length;

    const hasCanonical = /<link[^>]*rel=["']canonical["']/i.test(rawHtml);
    const hasMetaViewport = /<meta[^>]*name=["']viewport["']/i.test(rawHtml);
    const hasOpenGraph = /<meta[^>]*property=["']og:/i.test(rawHtml);
    const hasTwitterCard = /<meta[^>]*name=["']twitter:/i.test(rawHtml);

    // Schema
    const schemaScripts = [];
    const schemaMatches = [...rawHtml.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
    schemaMatches.forEach(m => {
      try { schemaScripts.push(JSON.parse(m[1])); } catch(e) {}
    });
    const flatSchemas = schemaScripts.flatMap(s => Array.isArray(s) ? s : (s['@graph'] ? s['@graph'] : [s]));
    const hasArticleSchema = flatSchemas.some(s => ['Article','NewsArticle','BlogPosting','TechArticle'].includes(s?.['@type']));
    const hasFAQPageSchema = flatSchemas.some(s => s?.['@type'] === 'FAQPage');
    const hasOrganizationSchema = flatSchemas.some(s => ['Organization','LocalBusiness','Corporation'].includes(s?.['@type']));

    // Content signals
    const bodyText = cleanText.toLowerCase();
    const hasFAQContent = /frequently asked|faq|common questions/i.test(rawHtml) 
      || /id=["'][^"']*faq[^"']*["']/i.test(rawHtml)
      || rawHtml.toLowerCase().includes('class=') && rawHtml.toLowerCase().match(/class=["'][^"']*faq[^"']*["']/);
    const hasTOC = /table of contents|on this page|jump to section|contents/i.test(rawHtml);
    const hasAuthorBio = /written by|about the author|about the founder|meet the author/i.test(rawHtml);
    const first300Words = cleanText.split(/\s+/).slice(0, 300).join(' ');
    const hasDirectAnswer = /\d/.test(first300Words) && first300Words.length > 150;
    const hasTLDR = /tl;dr|key takeaways|quick summary|at a glance|in this article|highlights/i.test(rawHtml);

    // Images
    const imgMatches = [...rawHtml.matchAll(/<img[^>]*>/gi)];
    const contentImgs = imgMatches.filter(m => { const t = m[0].toLowerCase();
      if (/wp-content\/plugins|cookie|consent|placeholder|revisit|\/close|gravatar|emoji|wp-smiley|spinner|loader|tracking|1x1|spacer|sprite|favicon|\blogo|badge|\bicon|thumb|screenshot|\bflag|data:image/i.test(t)) return false;
      return true; });
    const images = contentImgs.length;
    const imagesWithAlt = contentImgs.filter(m => /alt=["'][^"']+["']/i.test(m[0]) && !/alt=["']?["']/i.test(m[0])).length;

    // Links
    const allLinks = [...rawHtml.matchAll(/<a[^>]*href=["']([^"']+)["']/gi)].map(m => m[1]);
    const _luc = (labelUrl || '').toLowerCase();
    const _cleanLinks = allLinks.map(h => (h || '').trim()).filter(h => { const x = h.toLowerCase(); return x && !x.startsWith('#') && !x.startsWith('mailto:') && !x.startsWith('tel:') && !x.startsWith('javascript:') && !x.includes('/cdn-cgi/'); });
    const internalLinks = [...new Set(_cleanLinks.filter(h => { const x = h.toLowerCase(); return !x.startsWith('http') || (_luc && x.includes(_luc)); }))].length;
    const externalLinks = [...new Set(_cleanLinks.filter(h => { const x = h.toLowerCase(); return x.startsWith('http') && !(_luc && x.includes(_luc)); }))].length;

    // Quotes & case studies
    const bqCount = ([...rawHtml.matchAll(/<blockquote/gi)]).length;
    const citeCount = ([...rawHtml.matchAll(/<cite[\s>]/gi)]).length;
    const expertQuoteCount = Math.max(bqCount, citeCount);

    const caseStudyKeywords = ['case study','challenge','solution','results','roi','recovered'];
    const caseStudyCount = caseStudyKeywords.reduce((sum, kw) => sum + (bodyText.split(kw).length - 1), 0);

    const statsPattern = /\d+%|\$[\d,.]+|€[\d,.]+|\d{1,3}(,\d{3})+|\d+x\s/g;
    const statsFound = (cleanText.match(statsPattern) || []).length;

    // Structural audit counts (live parse-bug detection — deterministic, no AI)
    const headCount    = (rawHtml.match(/<head\b/gi) || []).length;
    const footerCount  = (rawHtml.match(/<footer\b/gi) || []).length;
    const doctypeCount = (rawHtml.match(/<!doctype/gi) || []).length;
    const htmlTagCount = (rawHtml.match(/<html\b/gi) || []).length;
    const bodyCount    = (rawHtml.match(/<body\b/gi) || []).length;
    const csNavCount   = (rawHtml.match(/class=["'][^"']*cs-nav/gi) || []).length;
    const csBadgeCount = (rawHtml.match(/data-cs-badge/gi) || []).length;

    // Build analysis object matching the browser evaluate() output
    const analysis = {
      wordCount, h1Count, h1Text, h1Length, 
      h1IsHidden: false, h1VisibleCount: h1Count, 
      h1IsGeneric, h1IsTooShort, h1IsTooLong,
      h2Count, h3Count, listItemCount, avgParagraphLength,
      metaTitleLength, metaDescriptionLength,
      hasMetaViewport, hasCanonical,
      hasOpenGraph, hasTwitterCard,
      hasArticleSchema, hasFAQPageSchema, hasOrganizationSchema,
      hasFAQContent, images, imagesWithAlt,
headCount, footerCount, doctypeCount, htmlTagCount, bodyCount, csNavCount, csBadgeCount,
      internalLinks, externalLinks,
      expertQuoteCount, caseStudyCount, statsFound,
      hasDirectAnswer, hasTLDR, hasTOC, hasAuthorBio
    };

    const result = computeScore(scanUrl, analysis, []);
    console.log(`✅ scan/paste: ${scanUrl} → ${result.score}/100 (${wordCount} words)`);
    res.json(result);
    // Save to scan_log so badge can find paste scans too
    if (pool && scanUrl !== 'pasted-html') {
      pool.query(
        `INSERT INTO scan_log (business_url, score, source, created_at) VALUES ($1, $2, 'paste', NOW())`,
        [scanUrl, result.score]
      ).catch(err => console.error('[paste scan_log] insert failed:', err.message, '| url:', scanUrl));
        _badgeBust(scanUrl);
    }
  } catch (error) {
    console.error('❌ scan/paste error:', error.message);
    res.status(500).json({ success: false, error: 'Paste scan failed: ' + error.message });
  }
});


