// ══════════════════════════════════════════════════════════════════════
// SITEMAP FETCH — /api/fetch-sitemap?url=
// Fetches a sitemap.xml and returns all page URLs
// ══════════════════════════════════════════════════════════════════════
app.get('/api/fetch-sitemap', async (req, res) => {
  const { url, try_paths } = req.query;
  if (!url) return res.status(400).json({ error: 'url required' });

  // Build list of URLs to try
  const urlsToTry = [url];
  if (try_paths) {
    const extra = try_paths.split(',').map(p => p.trim()).filter(Boolean);
    for (const u of extra) { if (!urlsToTry.includes(u)) urlsToTry.push(u); }
  }

  let lastError = '';
  for (const fetchUrl of urlsToTry) {
    try {
      console.log(`[sitemap] trying: ${fetchUrl}`);
      let xmlText = '';

      // Try axios
      try {
        const resp = await axios.get(fetchUrl, {
          timeout: 15000,
          headers: { 'User-Agent': 'ContentScaleBot/1.0' },
          responseType: 'text',
          maxRedirects: 5
        });
        xmlText = typeof resp.data === 'string' ? resp.data : JSON.stringify(resp.data);
      } catch (axiosErr) {
        // Try www variant
        const alt = fetchUrl.includes('://www.')
          ? fetchUrl.replace('://www.', '://')
          : fetchUrl.replace('://', '://www.');
        try {
          const resp2 = await axios.get(alt, { timeout: 15000, headers: { 'User-Agent': 'ContentScaleBot/1.0' }, responseType: 'text', maxRedirects: 5 });
          xmlText = typeof resp2.data === 'string' ? resp2.data : JSON.stringify(resp2.data);
        } catch (e2) {
          lastError = axiosErr.message;
          continue; // Try next path
        }
      }

      if (!xmlText || xmlText.length < 10) { lastError = 'Empty response'; continue; }

      // Parse URLs
      const locRegex = /<loc>(.*?)<\/loc>/gi;
      const urls = [], subSitemaps = [];
      let match;
      while ((match = locRegex.exec(xmlText)) !== null) {
        const u = match[1].trim();
        if (!u) continue;
        if (u.endsWith('.xml')) subSitemaps.push(u);
        else urls.push(u);
      }
      console.log(`[sitemap] ${fetchUrl} => ${urls.length} page URLs, ${subSitemaps.length} sub-sitemaps`);

      // If sitemap index, auto-fetch sub-sitemap
      if (urls.length === 0 && subSitemaps.length > 0) {
        const preferred = subSitemaps.find(u => u.includes('page')) || subSitemaps[0];
        try {
          const sub = await axios.get(preferred, { timeout: 15000, headers: { 'User-Agent': 'ContentScaleBot/1.0' }, responseType: 'text' });
          const subXml = typeof sub.data === 'string' ? sub.data : '';
          const subRegex = /<loc>(.*?)<\/loc>/gi;
          let sm;
          while ((sm = subRegex.exec(subXml)) !== null) {
            const u = sm[1].trim();
            if (u && !u.endsWith('.xml')) urls.push(u);
          }
        } catch(e) { /* sub-sitemap fetch failed */ }
      }

      // Return if we found URLs
      if (urls.length > 0) {
        return res.json({ success: true, urls, subSitemaps, count: urls.length, fetched_from: fetchUrl });
      }

      lastError = 'No URLs found in XML';
    } catch(e) {
      lastError = e.message;
    }
  }

  // All paths failed
  console.error(`[sitemap] all paths failed. Last error: ${lastError}`);
  res.status(500).json({ success: false, error: `Tried ${urlsToTry.length} path(s). Last error: ${lastError}` });
});

// GSC AUTO-FILL — /api/gsc/auto-fill
// Haalt GSC data op voor een specifieke pagina via Service Account
// Vereist: GSC_SERVICE_ACCOUNT_JSON env var in Railway
// ══════════════════════════════════════════════════════════════════════
app.post('/api/gsc/auto-fill', async (req, res) => {
  if (!_gscServiceAccount) {
    return res.status(503).json({
      success: false,
      error: 'GSC_SERVICE_ACCOUNT_JSON niet geconfigureerd in Railway Variables'
    });
  }

  const { pageUrl } = req.body;
  if (!pageUrl) return res.status(400).json({ success: false, error: 'pageUrl required' });

  try {
    const urlObj = new URL(pageUrl);

    // Helper: try a GSC query with a given siteUrl, return rows or throw
    async function tryGscQuery(accessToken, siteUrlToTry, dims, filterPage, startDate, endDate) {
      const body = { startDate, endDate, dimensions: dims,
        dimensionFilterGroups: filterPage ? [{ filters: [{ dimension: 'page', operator: 'equals', expression: pageUrl }] }] : [],
        rowLimit: 20 };
      const r = await fetch(
        `https://www.googleapis.com/webmasters/v3/sites/${encodeURIComponent(siteUrlToTry)}/searchAnalytics/query`,
        { method: 'POST', headers: { Authorization: `Bearer ${accessToken}` }, body: JSON.stringify(body) }
      );
      if (!r.ok) { const e = await r.json(); throw new Error(e.error?.message || r.status); }
      return (await r.json()).rows || [];
    }

    const now = Math.floor(Date.now() / 1000);
    const { createSign } = require('crypto');
    const header = Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64url');
    const payload = Buffer.from(JSON.stringify({
      iss: _gscServiceAccount.client_email,
      scope: 'https://www.googleapis.com/auth/webmasters.readonly',
      aud: 'https://oauth2.googleapis.com/token',
      exp: now + 3600,
      iat: now
    })).toString('base64url');

    const sign = createSign('RSA-SHA256');
    sign.update(`${header}.${payload}`);
    const signature = sign.sign(_gscServiceAccount.private_key, 'base64url');
    const jwt = `${header}.${payload}.${signature}`;

    const tokenResp = await axios.post('https://oauth2.googleapis.com/token',
      new URLSearchParams({
        grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
        assertion: jwt
      }).toString(),
      { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
    );

    const accessToken = tokenResp.data.access_token;
    const endDate = new Date().toISOString().split('T')[0];
    const startDate = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    // Try multiple site URL formats — GSC properties can be registered differently
    const siteUrlFormats = [
      `https://${urlObj.hostname}/`,
      `http://${urlObj.hostname}/`,
      `sc-domain:${urlObj.hostname.replace(/^www\./, '')}`,
      `https://www.${urlObj.hostname.replace(/^www\./, '')}/`,
    ];

    let pageRows = [], queryRows = [], usedSiteUrl = '';
    for (const fmt of siteUrlFormats) {
      try {
        pageRows = await tryGscQuery(accessToken, fmt, ['page'], true, startDate, endDate);
        queryRows = await tryGscQuery(accessToken, fmt, ['query'], true, startDate, endDate);
        usedSiteUrl = fmt;
        console.log(`[gsc] Using site format: ${fmt}`);
        break;
      } catch(e) {
        console.log(`[gsc] Format ${fmt} failed: ${e.message}`);
      }
    }

    if (!usedSiteUrl) {
      // No GSC property matched — return clean error, not 500
      return res.status(404).json({
        success: false,
        error: 'No GSC property found for this site. The service account may not have access, or the site is not registered in Search Console.',
        hint: 'You can still enter GSC data manually below, or upload CSV files from Search Console.',
        code: 'GSC_PROPERTY_NOT_FOUND'
      });
    }

    let impressions = 0, clicks = 0, ctr = 0, position = 0;
    if (pageRows.length > 0) {
      impressions = Math.round(pageRows[0].impressions || 0);
      clicks = Math.round(pageRows[0].clicks || 0);
      ctr = parseFloat(((pageRows[0].ctr || 0) * 100).toFixed(2));
      position = parseFloat((pageRows[0].position || 0).toFixed(1));
    }

    // Mobile % — query by device dimension
    let mobilePct = null;
    try {
      const mobileRows = await tryGscQuery(accessToken, usedSiteUrl, ['device'], true, startDate, endDate);
      if (mobileRows.length) {
        const total = mobileRows.reduce((a, r) => a + (r.clicks || 0), 0);
        const mRow = mobileRows.find(r => (r.keys[0]||'').toUpperCase() === 'MOBILE');
        if (mRow && total > 0) mobilePct = Math.round((mRow.clicks / total) * 100);
      }
    } catch(e) { /* mobile is optional */ }

    // Sort by impressions descending — highest volume query first
    const sortedByImpr = [...queryRows].sort((a, b) => (b.impressions||0) - (a.impressions||0));
    const topQueries = sortedByImpr.slice(0, 15).map(r => r.keys[0]).join('\n');
    const topKeyword = sortedByImpr[0]?.keys[0] || '';
    const topKeywordImpr = Math.round(sortedByImpr[0]?.impressions || 0);

    console.log(`[gsc] ${pageUrl} => ${impressions} impr ${ctr}% CTR pos ${position} | top kw: "${topKeyword}" (${topKeywordImpr} impr)`);

    res.json({
      success: true,
      data: { impressions, clicks, ctr, position, topQueries, topKeyword, topKeywordImpr,
              mobilePct, queryCount: queryRows.length, dateRange: `${startDate} => ${endDate}` }
    });

  } catch(e) {
    const msg = e.response && e.response.data && e.response.data.error
      ? (e.response.data.error.message || e.response.data.error)
      : e.message;
    console.error('[gsc] error:', msg);
    // Return appropriate status codes — NOT 500 for expected errors
    if (msg.includes('403') || msg.includes('Forbidden') || msg.includes('insufficientPermission')) {
      return res.status(403).json({
        success: false,
        error: 'GSC access denied. Add the service account to your Search Console property.',
        hint: 'seo-audit-tool-service-account@pure-heuristic-473710-t1.iam.gserviceaccount.com',
        code: 'GSC_ACCESS_DENIED'
      });
    }
    if (msg.includes('404') || msg.includes('notFound') || msg.includes('No data') || msg.includes('empty')) {
      return res.status(404).json({
        success: false,
        error: 'No GSC data for this URL. The page may not be indexed or has no traffic yet.',
        hint: 'You can still enter GSC data manually in the form below.',
        code: 'GSC_NO_DATA'
      });
    }
    if (msg.includes('401') || msg.includes('unauthorized') || msg.includes('invalid_grant')) {
      return res.status(401).json({
        success: false,
        error: 'GSC service account authentication failed.',
        hint: 'Check that GSC_SERVICE_ACCOUNT_JSON is set correctly in your Railway variables.',
        code: 'GSC_AUTH_FAILED'
      });
    }
    // Only return 500 for truly unexpected errors
    res.status(500).json({ success: false, error: msg });
  }
});

// ── GSC AUTO-DISCOVERY (no manual search, no CSV) ────────────────────────────
// Reusable service-account access token (webmasters.readonly)
async function _getGscAccessToken(){
  if(!_gscServiceAccount) throw new Error('GSC_SERVICE_ACCOUNT_JSON not configured');
  const now = Math.floor(Date.now()/1000);
  const { createSign } = require('crypto');
  const header = Buffer.from(JSON.stringify({ alg:'RS256', typ:'JWT' })).toString('base64url');
  const payload = Buffer.from(JSON.stringify({
    iss: _gscServiceAccount.client_email,
    scope: 'https://www.googleapis.com/auth/webmasters.readonly',
    aud: 'https://oauth2.googleapis.com/token',
    exp: now + 3600, iat: now
  })).toString('base64url');
  const sign = createSign('RSA-SHA256'); sign.update(header + '.' + payload);
  const _pk = String(_gscServiceAccount.private_key || '').replace(/\\n/g, '\n');
  const signature = sign.sign(_pk, 'base64url');
  const jwt = header + '.' + payload + '.' + signature;
  const tokenResp = await axios.post('https://oauth2.googleapis.com/token',
    new URLSearchParams({ grant_type:'urn:ietf:params:oauth:grant-type:jwt-bearer', assertion: jwt }).toString(),
    { headers: { 'Content-Type':'application/x-www-form-urlencoded' } });
  return tokenResp.data.access_token;
}

// GET /api/gsc/sites — auto-discover ALL GSC properties the service account can access
app.get('/api/gsc/sites', verifyAdmin, async (req, res) => {
  if(!_gscServiceAccount) return res.status(503).json({ success:false, error:'GSC_SERVICE_ACCOUNT_JSON not configured in Railway Variables' });
  try {
    const accessToken = await _getGscAccessToken();
    const r = await fetch('https://www.googleapis.com/webmasters/v3/sites', { headers:{ Authorization:'Bearer ' + accessToken } });
    if(!r.ok){ const e = await r.json().catch(()=>({})); return res.status(r.status).json({ success:false, error:(e.error&&e.error.message)||('HTTP '+r.status) }); }
    const data = await r.json();
    const entries = (data.siteEntry||[]).filter(s => s.permissionLevel && s.permissionLevel !== 'siteUnverifiedUser');
    entries.sort((a,b)=>{
      const ad = a.siteUrl.indexOf('sc-domain:')===0?0:1, bd = b.siteUrl.indexOf('sc-domain:')===0?0:1;
      if(ad!==bd) return ad-bd;
      return a.siteUrl.localeCompare(b.siteUrl);
    });
    res.json({ success:true, count:entries.length, sites: entries.map(s=>({ siteUrl:s.siteUrl, permission:s.permissionLevel, is_domain: s.siteUrl.indexOf('sc-domain:')===0 })) });
  } catch(e){ const detail = (e && e.response && e.response.data && (e.response.data.error_description || e.response.data.error || JSON.stringify(e.response.data))) || (e && e.message) || 'Unknown error'; console.error('[gsc/sites]', detail); res.status(500).json({ success:false, error: detail }); }
});

// GET /api/gsc/site-pages?siteUrl=...&days=90&limit=200 — pull top pages for a property (auto-import source, no CSV)
app.get('/api/gsc/site-pages', verifyAdmin, async (req, res) => {
  if(!_gscServiceAccount) return res.status(503).json({ success:false, error:'GSC_SERVICE_ACCOUNT_JSON not configured' });
  const siteUrl = req.query.siteUrl;
  if(!siteUrl) return res.status(400).json({ success:false, error:'siteUrl required (get it from /api/gsc/sites)' });
  const days = Math.min(parseInt(req.query.days,10)||90, 480);
  const rowLimit = Math.min(parseInt(req.query.limit,10)||200, 1000);
  try {
    const accessToken = await _getGscAccessToken();
    const endDate = new Date().toISOString().split('T')[0];
    const startDate = new Date(Date.now() - days*864e5).toISOString().split('T')[0];
    const body = { startDate, endDate, dimensions:['page'], rowLimit };
    const r = await fetch('https://www.googleapis.com/webmasters/v3/sites/' + encodeURIComponent(siteUrl) + '/searchAnalytics/query',
      { method:'POST', headers:{ Authorization:'Bearer ' + accessToken, 'Content-Type':'application/json' }, body: JSON.stringify(body) });
    if(!r.ok){ const e = await r.json().catch(()=>({})); return res.status(r.status).json({ success:false, error:(e.error&&e.error.message)||('HTTP '+r.status) }); }
    const data = await r.json();
    const pages = (data.rows||[]).map(row=>({
      url: (row.keys && row.keys[0]) || '',
      clicks: Math.round(row.clicks||0),
      impressions: Math.round(row.impressions||0),
      ctr: parseFloat(((row.ctr||0)*100).toFixed(2)),
      position: parseFloat((row.position||0).toFixed(1))
    })).filter(p => p.url);
    res.json({ success:true, siteUrl, days, count:pages.length, pages });
  } catch(e){ const detail = (e && e.response && e.response.data && (e.response.data.error_description || e.response.data.error || JSON.stringify(e.response.data))) || (e && e.message) || 'Unknown error'; console.error('[gsc/site-pages]', detail); res.status(500).json({ success:false, error: detail }); }
});


