app.post('/api/campaigns/login', async (req, res) => {
  const { code } = req.body || {};
  if (!code) return res.status(400).json({ error: 'Access code required' });
  try {
    const r = await pool.query('SELECT * FROM campaign_clients WHERE access_code=$1', [code.trim()]);
    if (!r.rows.length) return res.status(401).json({ error: 'Invalid access code' });
    const client = r.rows[0];
    if (!client.is_active) return res.status(403).json({ error: 'Account blocked — contact Ottmar at ContentScale' });
    await pool.query('UPDATE campaign_clients SET last_login=NOW() WHERE id=$1', [client.id]);
    res.json({ ok: true, client: { id: client.id, name: client.name, company: client.company,
      isTest: client.is_test, testCallsLimit: client.test_calls_limit,
      testCallsUsed: client.test_calls_used, minutesUsed: client.minutes_used,
      minutesLimit: client.minutes_limit, voice: client.voice,
      vapiPhoneId: client.vapi_phone_id, vapiKey: client.vapi_key } });
  } catch(e) { res.status(500).json({ error: e.message }); }
});

