// GET /api/admin/ip-geo?ip=x.x.x.x — geolocate IP for admin users panel
app.get('/api/admin/ip-geo', verifyAdmin, async (req, res) => {
  const ip = req.query.ip;
  if (!ip) return res.status(400).json({ error: 'ip required' });
  // Private/local IPs — skip lookup
  if (/^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.|127\.|::1)/.test(ip))
    return res.json({ country: 'Local', city: 'Local', countryCode: '', flag: '🏠' });
  try {
    const r = await fetch('http://ip-api.com/json/' + ip + '?fields=country,countryCode,city,status');
    const d = await r.json();
    if (d.status !== 'success') return res.json({ country: '?', city: '?', countryCode: '', flag: '🌐' });
    const flags = {'NL':'🇳🇱','US':'🇺🇸','DE':'🇩🇪','GB':'🇬🇧','FR':'🇫🇷','BE':'🇧🇪','AU':'🇦🇺','CA':'🇨🇦','PH':'🇵🇭','SG':'🇸🇬','IN':'🇮🇳','BR':'🇧🇷','ES':'🇪🇸','IT':'🇮🇹','PL':'🇵🇱','SE':'🇸🇪','NO':'🇳🇴','DK':'🇩🇰','FI':'🇫🇮','ZA':'🇿🇦'};
    res.json({ country: d.country, city: d.city, countryCode: d.countryCode, flag: flags[d.countryCode] || '🌐' });
  } catch(e) {
    res.json({ country: '?', city: '?', countryCode: '', flag: '🌐' });
  }
});

// ── TWILIO LOOKUP — check if number is mobile/landline ───────────────────────
app.get('/api/lookup/number', async (req, res) => {
  const { phone } = req.query;
  if (!phone) return res.status(400).json({ error: 'phone required' });

  const sid   = process.env.TWILIO_ACCOUNT_SID;
  const token = process.env.TWILIO_AUTH_TOKEN;
  if (!sid || !token) return res.status(500).json({ error: 'TWILIO_ACCOUNT_SID / TWILIO_AUTH_TOKEN not set in Railway' });

  try {
    const encoded = encodeURIComponent(phone);
    const r = await fetch(
      `https://lookups.twilio.com/v2/PhoneNumbers/${encoded}?Fields=line_type_intelligence`,
      { headers: { 'Authorization': 'Basic ' + Buffer.from(sid + ':' + token).toString('base64') } }
    );
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ error: d.message || 'Lookup failed' });

    const lineType = d.line_type_intelligence?.type || 'unknown'; // mobile | landline | voip | unknown
    const carrier  = d.line_type_intelligence?.carrier_name || '';
    const country  = d.country_code || '';

    // Map to simple label
    const isMobile   = lineType === 'mobile' || lineType === 'nonFixedVoip';
    const isLandline = lineType === 'landline' || lineType === 'fixedVoip';

    res.json({ phone, lineType, isMobile, isLandline, carrier, country,
      badge: isMobile ? '📱 Mobile' : isLandline ? '📞 Landline' : '❓ ' + lineType,
      aiCallAllowed: !isMobile // landline/voip = AI ok, mobile = manual only
    });
  } catch(e) {
    res.status(502).json({ error: e.message });
  }
});

