// ── Access Codes API ─────────────────────────────────────────────────────────
// POST /api/access/verify — klant logt in met code
app.post('/api/access/verify', async (req, res) => {
  const { code } = req.body;
  if (!code) return res.status(400).json({ success: false, error: 'Code verplicht' });
  if (!pool) return res.status(503).json({ success: false, error: 'DB niet beschikbaar' });
  try {
    const r = await pool.query(
      `SELECT * FROM access_codes WHERE code = $1 AND is_active = TRUE AND (expires_at IS NULL OR expires_at > NOW())`,
      [code.trim().toUpperCase()]
    );
    if (!r.rows.length) return res.status(401).json({ success: false, error: 'Ongeldige of verlopen code' });
    const ac = r.rows[0];
    if (ac.ai_calls_limit > 0 && ac.ai_calls_used >= ac.ai_calls_limit)
      return res.status(403).json({ success: false, error: 'AI-limiet bereikt voor deze code' });
    const token = require('crypto').randomBytes(32).toString('hex');
    await pool.query(
      `INSERT INTO access_sessions (token, code_id) VALUES ($1, $2)`,
      [token, ac.id]
    );
    res.json({ success: true, token, session: token, type: ac.type, client_name: ac.client_name });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

// GET /api/access/session — valideer sessie token
app.get('/api/access/session', async (req, res) => {
  const token = req.headers['x-access-token'];
  if (!token) return res.status(401).json({ success: false, error: 'Geen token' });
  if (!pool) return res.status(503).json({ success: false, error: 'DB niet beschikbaar' });
  try {
    const r = await pool.query(
      `SELECT s.*, c.type, c.client_name, c.is_active, c.ai_calls_used, c.ai_calls_limit
       FROM access_sessions s
       JOIN access_codes c ON c.id = s.code_id
       WHERE s.token = $1 AND s.expires_at > NOW() AND c.is_active = TRUE`,
      [token]
    );
    if (!r.rows.length) return res.status(401).json({ success: false, error: 'Sessie verlopen of ongeldig' });
    const s = r.rows[0];
    res.json({ success: true, type: s.type, client_name: s.client_name, ai_calls_used: s.ai_calls_used, ai_calls_limit: s.ai_calls_limit });
  } catch (e) { res.status(500).json({ success: false, error: e.message }); }
});

