        async function saveAdminSettings() {
            var email = document.getElementById('settingContactEmail').value.trim();
            var name = document.getElementById('settingSenderName').value.trim();
            var briefEmails = (document.getElementById('settingEngineBriefEmails')||{}).value || '';
            var briefWriters = (document.getElementById('settingEngineBriefWriters')||{}).value || '';
            var keepRules = (document.getElementById('settingKeepRules')||{}).value || '';
            if (!email) { alert('Enter an email address'); return; }
            try {
                var d = await apiCall('/api/admin/settings', 'POST', { engine_from_email: email, engine_sender_name: name, engine_brief_emails: briefEmails, engine_brief_writers: briefWriters, rewrite_keep_rules: keepRules });
                if (d.success) {
                    var saved = document.getElementById('settingsSaved');
                    if (saved) { saved.style.display='inline'; setTimeout(function(){ saved.style.display='none'; }, 3000); }
                } else { alert('Error: ' + (d.error||'Failed')); }
            } catch(e) { alert('Error: ' + e.message); }
        }

        async function recalcMaxPages() {
            try {
                var dbg = await apiCall('/api/admin/tracker-clients/debug-pages', 'GET');
                if (!dbg.success) { alert('Error: ' + dbg.error); return; }
                var wrong = dbg.clients.filter(function(c){ return c.status.indexOf('WRONG') > -1; });
                var msg = dbg.summary + '. Wrong clients: ';
                wrong.forEach(function(c){ msg += c.domain + ' (' + c.current_max_pages + '->' + c.correct_max_pages + ') '; });
                if (!confirm(msg + ' -- Fix now?')) return;
                var d = await apiCall('/api/admin/tracker-clients/recalc-max-pages', 'POST', {});
                if (d.success) {
                    alert('Fixed ' + d.fixed + ' client(s). Reload to see updated values.');
                    setTimeout(loadTrackerClients, 400);
                } else { alert('Error: ' + (d.error||'Failed')); }
            } catch(e) { alert('Error: ' + e.message); }
        }

        async function mergeDuplicateTrackers() {
            if (!confirm('This will find all duplicate domains and merge them into one account (keeping the oldest). Continue?')) return;
            try {
                var d = await apiCall('/api/admin/tracker-clients/merge-duplicates', 'POST', {});
                if (d.success) {
                    alert('Merged: ' + (d.merged || 0) + ' duplicate(s). ' + (d.details || 'No duplicates found'));
                    setTimeout(loadTrackerClients, 600);
                } else {
                    alert('Error: ' + (d.error || 'Failed'));
                }
            } catch(e) { alert('Error: ' + e.message); }
        }

        var _showDeleted = false;

        async function loadTrackerClients() {
            var el = document.getElementById('tcList');
            if (!el) return;
            el.innerHTML = '<div style="color:#6b7280;padding:20px;text-align:center;">Loading...</div>';
            try {
                var url = '/api/admin/tracker-clients' + (_showDeleted ? '?include_deleted=1' : '');
                var data = await apiCall(url);
                _tcClients = data.clients || [];
                renderTrackerClients(_tcClients);
                var active = _tcClients.filter(function(c){ return c.status === 'active'; }).length;
                var pages = _tcClients.reduce(function(a,c){ return a + parseInt(c.page_count||0); }, 0);
                var withEmail = _tcClients.filter(function(c){ return c.email; }).length;
                var withWa = _tcClients.filter(function(c){ return c.whatsapp; }).length;
                var dealifyCount = _tcClients.filter(function(c){ return !!c.dealify_codes; }).length;
                var freeCount = _tcClients.filter(function(c){ return !c.dealify_codes && (c.max_pages||3) <= 3; }).length;
                var ownCount = _tcClients.filter(function(c){ return !c.dealify_codes && (c.max_pages||3) > 3; }).length;
                var s = function(id, v){ var e = document.getElementById(id); if(e) e.textContent = v; };
                s('tcStatTotal', _tcClients.length);
                s('tcStatActive', active);
                s('tcStatPages', pages);
                s('tcStatWithEmail', withEmail);
                s('tcStatWithWa', withWa);
                var activePages = _tcClients.filter(function(c){ return c.status === 'active'; }).reduce(function(a,c){ return a + parseInt(c.page_count||0); }, 0);
                s('tcStatScansDay', Math.ceil(activePages / 3));
                // Type breakdown in title attributes
                var totalEl = document.getElementById('tcStatTotal');
                if (totalEl) totalEl.title = 'Free: ' + freeCount + ' · Own: ' + ownCount + ' · Dealify: ' + dealifyCount;
            } catch(e) {
                el.innerHTML = '<div style="color:#f87171;padding:20px;">Error: ' + e.message + '</div>';
            }
        }

        var _tcTypeFilter = 'all';
        function openNewOwnClient() {
            var name = prompt('Client name:');
            if (name === null) return;
            var domain = prompt('Domain (without https/www):');
            if (!domain) return;
            var email = prompt('Email address:');
            var tier = prompt('Tier: 1=Tier1 (10 pages, €97) · 2=Tier2 (20 pages, €297) · or enter custom number:', '1');
            if (tier === null) return;
            var maxPages = tier === '1' ? 10 : tier === '2' ? 20 : (parseInt(tier) || 10);
            if (!confirm('Create: ' + domain + ' · ' + name + ' · ' + email + ' · ' + maxPages + ' pages · Welcome email: yes')) return;
            apiCall('/api/admin/tracker-clients/create-own', 'POST', {
                domain: domain.trim(), name: name.trim(), email: (email||'').trim(), max_pages: maxPages, source: 'own'
            }).then(function(d) {
                if (d.success) {
                    alert('Client created! URL: ' + d.url + ' — Welcome email sent to: ' + (email||'no email'));
                    loadTrackerClients();
                } else { alert('Error: ' + (d.error||'Failed')); }
            }).catch(function(e){ alert('Error: ' + e.message); });
        }
        function filterTcType(type) {
            _tcTypeFilter = type;
            ['all','free','own','dealify'].forEach(function(t) {
                var btn = document.getElementById('tcType' + t.charAt(0).toUpperCase() + t.slice(1));
                if (btn) btn.style.background = t === type ? (t==='all'?'#374151':t==='dealify'?'rgba(245,158,11,.15)':t==='own'?'rgba(167,139,250,.15)':'rgba(107,114,128,.15)') : '';
            });
            filterTrackerClients();
        }

        function filterTrackerClients() {
            var q = (document.getElementById('tcSearch').value||'').toLowerCase();
            var filtered = _tcClients.filter(function(c){
                var matchQ = !q || (c.domain||'').toLowerCase().indexOf(q) > -1
                    || (c.name||'').toLowerCase().indexOf(q) > -1
                    || (c.email||'').toLowerCase().indexOf(q) > -1;
                var matchType = _tcTypeFilter === 'all' ? true
                    : _tcTypeFilter === 'dealify' ? !!c.dealify_codes
                    : _tcTypeFilter === 'own' ? (!c.dealify_codes && (c.max_pages||3) > 3)
                    : _tcTypeFilter === 'free' ? (!c.dealify_codes && (c.max_pages||3) <= 3)
                    : true;
                return matchQ && matchType;
            });
            renderTrackerClients(filtered);
        }

