app.post('/api/tracker/pages/:id/push-to-rewrite', verifyEngineAccess, async (req, res) => {
  try {
    const eu = req.engineUser;
    const pageId = parseInt(req.params.id);
    if (!eu.isAdmin) {
      const own = await pool.query('SELECT id FROM tracker_pages WHERE id=$1 AND engine_code_id=$2', [pageId, eu.codeId]);
      if (!own.rows.length) return res.status(403).json({ success: false, error: 'Not found or access denied' });
    }

    const pageR = await pool.query('SELECT * FROM tracker_pages WHERE id=$1', [pageId]);
    if (!pageR.rows.length) return res.status(404).json({ success: false, error: 'Page not found' });
    const page = pageR.rows[0];

    // Get latest snapshot
    const snapR = await pool.query(
      `SELECT * FROM tracker_snapshots WHERE page_id=$1 ORDER BY checked_at DESC LIMIT 1`, [pageId]
    );
    const snap = snapR.rows[0] || {};

    // Get the baseline (first snapshot)
    const baseR = await pool.query(
      `SELECT * FROM tracker_snapshots WHERE page_id=$1 ORDER BY checked_at ASC LIMIT 1`, [pageId]
    );
    const baseline = baseR.rows[0] || {};

    // Build rewrite payload
    const rewritePayload = {
      profile_id: page.profile_id,
      original_url: page.url,
      current_slug: page.slug,
      current_title: page.title || '',
      keyword: page.keyword || '',
      // GSC data from tracker baseline + current
      gsc_impressions: snap.google_impressions || page.gsc_impressions || null,
      gsc_clicks: snap.google_clicks || page.gsc_clicks || null,
      gsc_position: snap.google_position || page.gsc_position || null,
      gsc_ctr: snap.google_ctr || page.gsc_ctr || null,
      gsc_keyword: page.gsc_keyword || page.keyword || '',
      gsc_queries: page.gsc_queries || null,
      gsc_pages: page.gsc_pages || null,
      // Competitor context from latest snapshot
      latest_snapshot_id: snap.id,
      ai_citations: {
        google_overview: snap.ai_google_overview_cited,
        perplexity: snap.ai_perplexity_cited,
        youcom: snap.ai_bing_cited
      },
      recommendations: safeJson(snap.recommendations, []),
      reason: 'Tracker classified as needing rewrite — position dropped or AI citation lost'
    };

    // Record the push
    await pool.query(
      `UPDATE tracker_classifications SET triggered_rewrite=TRUE, triggered_rewrite_at=NOW() WHERE page_id=$1 AND triggered_rewrite=FALSE`,
      [pageId]
    ).catch(()=>{});

    res.json({
      success: true,
      page_id: pageId,
      rewrite_payload: rewritePayload,
      redirect_to: 'rewrite_tab',
      message: 'Page pushed to Rewrite tab. Switch to the Rewrite tab — all current data is pre-filled.'
    });
  } catch(e) {
    console.error('[tracker-push-rewrite]', e);
    res.status(500).json({ success: false, error: e.message });
  }
});

// ── Live check status map ────────────────────────────────────────────────────
const _trackerCheckStatus = new Map();
// ── SSE Live Feed ─────────────────────────────────────────────────────────────
const _sseClients = new Set();
const _liveEvents = []; // last 50 events for new connections

function _sseBroadcast(event) {
  _liveEvents.unshift(event);
  if (_liveEvents.length > 50) _liveEvents.pop();
  const data = 'data: ' + JSON.stringify(event) + '\n\n';
  for (const client of _sseClients) {
    try { client.write(data); } catch(e) { _sseClients.delete(client); }
  }
}

// ── Live Wall SSE — per-token broadcast ──────────────────────────────────────
const _liveWallClients = new Map(); // token -> Set of res

function _liveWallBroadcast(token, event) {
  const clients = _liveWallClients.get(token);
  if (!clients) return;
  const dead = [];
  const data = 'event: ' + (event.type || 'message') + '\ndata: ' + JSON.stringify(event) + '\n\n';
  for (const res of clients) {
    try { res.write(data); } catch(e) { dead.push(res); }
  }
  for (const d of dead) clients.delete(d);
}

// ── Polling fallback for live feed (Railway HTTP/2 SSE issues) ───────────────
app.get('/api/tracker/live-events', async (req, res) => {
  const token = req.query.token || req.headers['x-admin-key'] || '';
  if (!token) return res.status(401).json({ error: 'Auth required' });
  try {
    const r = await pool.query('SELECT * FROM super_admins WHERE session_token=$1 AND is_active=TRUE', [token]).catch(() => ({ rows: [] }));
    if (!r.rows.length) return res.status(401).json({ error: 'Invalid token' });
  } catch(e) { return res.status(500).json({ error: e.message }); }
  // Return last N events since a given timestamp
  const since = req.query.since ? new Date(req.query.since).getTime() : Date.now() - 30000;
  const events = _liveEvents.filter(e => new Date(e.ts||0).getTime() > since).slice(0, 20);
  res.json({ success: true, events, ts: new Date().toISOString() });
});

app.get('/api/tracker/live-feed', async (req, res) => {
  const token = req.query.token || req.headers['x-admin-key'] || '';
  if (!token) return res.status(401).json({ error: 'Auth required' });
  try {
    const r = await pool.query('SELECT * FROM super_admins WHERE session_token=$1 AND is_active=TRUE', [token]).catch(() => ({ rows: [] }));
    if (!r.rows.length) return res.status(401).json({ error: 'Invalid token' });
  } catch(e) { return res.status(500).json({ error: e.message }); }
  // Polling-only — Railway HTTP/2 breaks SSE
  const since = req.query.since ? new Date(req.query.since).getTime() : Date.now() - 30000;
  const events = _liveEvents.filter(e => new Date(e.ts||0).getTime() > since).slice(0, 20);
  res.json({ success: true, events, ts: new Date().toISOString() });
});

// ── Live Wall SSE endpoint (per tracker client) ──────────────────────────────
app.get('/api/tracker-client/:token/live-wall-stream', async (req, res) => {
  try {
    const cr = await pool.query('SELECT id, token, domain, live_wall_enabled FROM tracker_clients WHERE token=$1 AND (status IS NULL OR status != $2)', [req.params.token, 'deleted']);
    if (!cr.rows.length) return res.status(404).json({ success: false, error: 'Not found' });
    if (!cr.rows[0].live_wall_enabled) return res.status(403).json({ success: false, error: 'Live wall disabled' });
  } catch(e) { return res.status(500).json({ success: false, error: e.message }); }

  const token = req.params.token;

  res.socket.setNoDelay(true);
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache, no-transform');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');
  res.setHeader('Transfer-Encoding', 'identity');
  res.flushHeaders();

  // Register client
  if (!_liveWallClients.has(token)) _liveWallClients.set(token, new Set());
  _liveWallClients.get(token).add(res);

  // Send initial connected event
  res.write('event: connected\ndata: ' + JSON.stringify({ type: 'connected', ts: new Date().toISOString() }) + '\n\n');

  const hb = setInterval(() => {
    try { res.write(':hb\n\n'); }
    catch(e) {
      clearInterval(hb);
      const set = _liveWallClients.get(token);
      if (set) { set.delete(res); if (!set.size) _liveWallClients.delete(token); }
    }
  }, 25000);

  req.on('close', () => {
    clearInterval(hb);
    const set = _liveWallClients.get(token);
    if (set) { set.delete(res); if (!set.size) _liveWallClients.delete(token); }
  });
});

function _trSetStep(pageId, name, status, detail) {
  detail = detail || '';
  const state = _trackerCheckStatus.get(pageId);
  if(!state) return;
  const step = state.steps.find(function(s){ return s.name===name; });
  if(step) { step.status = status; step.detail = detail; }
  else state.steps.push({ name, status, detail });

  // Broadcast to SSE clients
  const labels = {
    html_hash: 'Fetching page',
    graaf_score: 'GRAAF scan',
    serp: 'Google position',
    ai_overview: 'AI Overview check',
    perplexity: 'Perplexity check',
    bing: 'Copilot/Bing check',
    recommendations: 'AI recommendations',
    save: 'Saving results'
  };
  const icons = {
    running: '⚙️', done: '✅', error: '❌', skipped: '⏭️'
  };
  const pageUrl = (state.url || '');
  const domain = pageUrl.replace(/^https?:\/\//, '').split('/')[0] || ('page #' + pageId);
  _sseBroadcast({
    type: 'step',
    pageId,
    domain,
    name,
    status,
    label: (icons[status]||'⚙️') + ' ' + (labels[name]||name),
    detail: detail.substring(0, 80),
    ts: new Date().toISOString()
  });
}

