// ── Simple text diff for content change detection ────────────────────────────
function computeTextDiff(oldHtml, newHtml) {
  if (!oldHtml || !newHtml) return null;
  function extractText(html) {
    return html
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ').trim();
  }
  const oldText = extractText(oldHtml);
  const newText = extractText(newHtml);
  const oldWords = new Set(oldText.toLowerCase().split(/\s+/).filter(w => w.length > 4));
  const newWords = new Set(newText.toLowerCase().split(/\s+/).filter(w => w.length > 4));
  const added = [...newWords].filter(w => !oldWords.has(w)).slice(0, 20);
  const removed = [...oldWords].filter(w => !newWords.has(w)).slice(0, 20);
  const oldLen = oldText.split(/\s+/).length;
  const newLen = newText.split(/\s+/).length;
  const wordCountDelta = newLen - oldLen;
  const changePct = oldLen > 0 ? Math.round(Math.abs(wordCountDelta) / oldLen * 100) : 0;
  return {
    words_added: added,
    words_removed: removed,
    word_count_before: oldLen,
    word_count_after: newLen,
    word_count_delta: wordCountDelta,
    change_percent: changePct,
    significant: changePct >= 10 || added.length >= 10 || removed.length >= 10
  };
}


// ── Telegram notification helper ─────────────────────────────────────────────
async function sendTelegramNotification(chatId, message) {
  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  if (!botToken || !chatId) return false;
  try {
    const resp = await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        chat_id: chatId,
        text: message,
        parse_mode: 'HTML',
        disable_web_page_preview: true
      })
    });
    const data = await resp.json();
    if (!data.ok) console.warn('[telegram] Send failed:', data.description);
    return data.ok;
  } catch(e) {
    console.warn('[telegram] Error:', e.message);
    return false;
  }
}

// ── notifyOttmar — Ottmar's own admin alert channel ──────────────────────
// Replaces CallMeBot (unreliable on free tier, 2026-07-22). Fires email
// (via the same Brevo key used for client tracker emails) and Telegram
// (ADMIN_TELEGRAM_CHAT_ID — Ottmar's own chat id, set once in Railway,
// separate from any client's telegram_chat_id) in parallel. Best-effort:
// never throws, so a failed notification never breaks the calling flow.
async function notifyOttmar(subject, htmlOrText, plainTextFallback) {
  const plain = plainTextFallback || String(htmlOrText || '').replace(/<[^>]+>/g, '');
  try {
    const brevoKey = process.env.BREVO_API_KEY;
    if (brevoKey) {
      const r = await fetch('https://api.brevo.com/v3/smtp/email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'api-key': brevoKey },
        body: JSON.stringify({
          to: [{ email: 'otteyfrancisca@gmail.com', name: 'Ottmar' }],
          sender: { email: process.env.FROM_EMAIL || 'info@contentscale.site', name: 'ContentScale Tracker' },
          subject: subject,
          htmlContent: '<div style="font-family:Verdana,Geneva,sans-serif;font-size:14px;color:#1e293b;">' + (htmlOrText || '') + '</div>'
        })
      });
      if (!r.ok) console.warn('[notifyOttmar] Brevo email failed', r.status);
    } else {
      console.warn('[notifyOttmar] BREVO_API_KEY not set — admin email skipped');
    }
  } catch (e) { console.warn('[notifyOttmar] email error:', e.message); }

  try {
    const adminChatId = process.env.ADMIN_TELEGRAM_CHAT_ID;
    if (adminChatId) await sendTelegramNotification(adminChatId, '⭐ <b>' + subject + '</b>\n' + plain);
  } catch (e) { console.warn('[notifyOttmar] telegram error:', e.message); }
}
// ── Telegram webhook — /start handler ────────────────────────────────────────
app.post('/api/telegram/webhook', async (req, res) => {
  res.json({ ok: true }); // Always respond quickly
  try {
    const update = req.body;
    console.log('[telegram-webhook] Received update:', JSON.stringify(update).substring(0, 300));
    const msg = update.message;
    if (!msg || !msg.text) {
      console.log('[telegram-webhook] No message/text in update');
      return;
    }

    const chatId = String(msg.chat.id);
    const text = msg.text.trim();
    const botToken = process.env.TELEGRAM_BOT_TOKEN;
    console.log('[telegram-webhook] chatId:', chatId, 'text:', text, 'hasToken:', !!botToken);
    if (!botToken) return;

    // /start command — may include tracker token as parameter
    if (text.startsWith('/start')) {
      const parts = text.split(' ');
      const trackerToken = parts[1] || null;

      if (trackerToken) {
        // Link this Telegram chat to the tracker account
        const cr = await pool.query('SELECT id, domain FROM tracker_clients WHERE token=$1', [trackerToken]);
        if (cr.rows.length) {
          await pool.query('UPDATE tracker_clients SET telegram_chat_id=$1 WHERE id=$2', [chatId, cr.rows[0].id]);
          // Welcome message
          await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              chat_id: chatId,
              text: `✅ <b>Telegram alerts enabled!</b>\n\nYou'll now receive Citation Brief updates for <b>${cr.rows[0].domain}</b> here.\n\nNo action needed — the system will notify you automatically after every scan.`,
              parse_mode: 'HTML'
            })
          });
          console.log('[telegram] Linked chat', chatId, 'to tracker', cr.rows[0].domain);
        } else {
          await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              chat_id: chatId,
              text: '⚠️ Tracker not found. Please use the link from your tracker page.',
              parse_mode: 'HTML'
            })
          });
        }
      } else {
        // Generic start without token
        await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            chat_id: chatId,
            text: '👋 <b>Welcome to ContentScale Tracker Bot!</b>\n\nTo enable alerts for your tracker, click the "Install Telegram" button in your tracker page.',
            parse_mode: 'HTML'
          })
        });
      }
    }
  } catch(e) { console.warn('[telegram-webhook]', e.message); }
});

// Register Telegram webhook on startup
async function registerTelegramWebhook() {
  const botToken = process.env.TELEGRAM_BOT_TOKEN;
  const appUrl = process.env.APP_URL;
  if (!botToken || !appUrl) return;
  try {
    const resp = await fetch(`https://api.telegram.org/bot${botToken}/setWebhook`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ url: appUrl + '/api/telegram/webhook' })
    });
    const data = await resp.json();
    if (data.ok) console.log('[telegram] Webhook registered:', appUrl + '/api/telegram/webhook');
    else console.warn('[telegram] Webhook registration failed:', data.description);
  } catch(e) { console.warn('[telegram] Webhook error:', e.message); }
}
setTimeout(registerTelegramWebhook, 5000);

// ── Paused account follow-up scheduler — runs every 24h ──────────────────────
function startPausedFollowupScheduler() {
  setTimeout(async function runPausedFollowup() {
    if (!pool) { setTimeout(runPausedFollowup, 24 * 60 * 60 * 1000); return; }
    try {
      console.log('[paused-followup] Checking paused accounts...');

      const clients = await pool.query(`
        SELECT c.*, p.url as page_url, p.brief_content, p.brief_done_at
        FROM tracker_clients c
        LEFT JOIN LATERAL (
          SELECT url, brief_content, brief_done_at FROM tracker_pages
          WHERE tracker_client_id = c.id AND is_active = TRUE
          ORDER BY created_at DESC LIMIT 1
        ) p ON true
        WHERE c.status = 'paused'
        AND c.email IS NOT NULL
        AND c.paused_at IS NOT NULL
      `);

      for (const c of clients.rows) {
        const pausedDays = Math.floor((Date.now() - new Date(c.paused_at || c.updated_at).getTime()) / (1000 * 60 * 60 * 24));
        const trackerUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + c.token;
        const ottmarWa = 'https://wa.me/31628073996?text=Hi+Ottmar,+I+want+to+reactivate+my+tracker+for+' + encodeURIComponent(c.domain || '');

        // DAY 3 — "here's what you missed"
        if (pausedDays >= 3 && pausedDays < 4) {
          const recs = c.brief_content ? (function(){ try { const b = typeof c.brief_content === 'string' ? JSON.parse(c.brief_content) : c.brief_content; return b.items || []; } catch(e){ return []; } })() : [];
          let recsHtml = '';
          if (recs.length) {
            recsHtml = '<div style="background:#f5f3ff;border:1px solid #ddd6fe;border-radius:8px;padding:14px 16px;margin-bottom:16px;">'
              + '<div style="font-size:11px;font-weight:700;color:#7c3aed;text-transform:uppercase;letter-spacing:.06em;margin-bottom:10px;">Your last Citation Brief</div>';
            recs.slice(0,3).forEach(function(r) {
              const pri = (r.priority||'').toLowerCase();
              const color = pri==='high'?'#dc2626':pri==='medium'||pri==='med'?'#d97706':'#16a34a';
              recsHtml += '<div style="border-left:3px solid ' + color + ';padding:6px 10px;margin-bottom:7px;background:#0d1117;border-radius:0 5px 5px 0;">'
                + '<div style="font-size:11px;font-weight:700;color:' + color + ';margin-bottom:3px;">' + (r.title||'') + '</div>'
                + '<div style="font-size:12px;color:#9ca3af;line-height:1.55;">' + (r.action||'') + '</div>'
                + '</div>';
            });
            recsHtml += '</div>';
          }

          await notifyClient(c.id,
            'Your tracker is paused — here\'s what you missed for ' + c.domain,
            '<h2 style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:10px;">Your tracker has been paused for 3 days</h2>'
            + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">Your domain <strong>' + c.domain + '</strong> is no longer being monitored for AI citations. Here\'s what was in your last Citation Brief before it paused:</p>'
            + recsHtml
            + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:16px;">To reactivate, contact Ottmar directly:</p>'
            + '<a href="' + ottmarWa + '" style="display:inline-block;background:#16a34a;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">WhatsApp Ottmar to reactivate &rarr;</a>'
          ).catch(()=>{});

          if (c.telegram_chat_id) {
            await sendTelegramNotification(c.telegram_chat_id, '📋 Your ContentScale tracker for ').catch(()=>{});
          }
          console.log('[paused-followup] Day 3 email sent to', c.email);
        }

        // DAY 7 — "Ottmar can do it for you"
        if (pausedDays >= 7 && pausedDays < 8) {
          await notifyClient(c.id,
            'Let Ottmar implement your Citation Brief for ' + c.domain,
            '<h2 style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:10px;">Your tracker has been paused for a week</h2>'
            + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">No worries — implementing SEO recommendations takes time. That\'s exactly why Ottmar offers a done-for-you service.</p>'
            + '<div style="background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:16px;margin-bottom:16px;">'
            + '<div style="font-size:14px;font-weight:700;color:#166534;margin-bottom:8px;">&#128161; Let Ottmar babysit your domain</div>'
            + '<div style="font-size:13px;color:#166534;line-height:1.7;margin-bottom:12px;">Ottmar implements every Citation Brief for you. Plus high-GRAAF, citation-ready content.</div>'
            + '<a href="' + ottmarWa + '" style="display:inline-block;background:#16a34a;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">WhatsApp Ottmar &rarr;</a>'
            + '</div>'
            + '<p style="font-size:12px;color:#94a3b8;">Your tracker will be deleted in 23 days if not reactivated.</p>'
          ).catch(()=>{});

          if (c.telegram_chat_id) {
            await sendTelegramNotification(c.telegram_chat_id, '💡 Your tracker for ').catch(()=>{});
          }
          console.log('[paused-followup] Day 7 email sent to', c.email);
        }

        // DAY 30 — delete account + final email
        if (pausedDays >= 30) {
          // Final email before deletion
          await notifyClient(c.id,
            'Your ContentScale tracker has been deleted — ' + c.domain,
            '<h2 style="font-size:17px;font-weight:800;color:#dc2626;margin-bottom:10px;">Your tracker data has been deleted</h2>'
            + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">Your tracker for <strong>' + c.domain + '</strong> has been automatically deleted after 30 days of inactivity.</p>'
            + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:16px;">If you want to start fresh, contact Ottmar to set up a new tracker:</p>'
            + '<a href="' + ottmarWa + '" style="display:inline-block;background:#7c3aed;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">Start fresh with Ottmar &rarr;</a>'
          ).catch(()=>{});

          // Delete pages + client
          await pool.query('UPDATE tracker_pages SET is_active=FALSE WHERE tracker_client_id=$1', [c.id]).catch(()=>{});
          await pool.query('UPDATE tracker_clients SET status=$1 WHERE id=$2', ['deleted', c.id]).catch(()=>{});
          console.log('[paused-followup] Day 30 — deleted account', c.id, c.domain);
        }

        await new Promise(r => setTimeout(r, 2000));
      }
    } catch(e) { console.warn('[paused-followup]', e.message); }

    setTimeout(runPausedFollowup, 24 * 60 * 60 * 1000);
  }, 7 * 60 * 1000); // first run 7 min after start
  console.log('[paused-followup] Paused account follow-up scheduler started');
}

startPausedFollowupScheduler();

// ── Daily HTML reminder + auto-pause — frequency-aware ─────────────────────────
function startHtmlReminderScheduler() {
  setTimeout(async function runHtmlReminder() {
    if (!pool) { setTimeout(runHtmlReminder, 24 * 60 * 60 * 1000); return; }
    try {
      console.log('[html-reminder] Running frequency-aware reminder check...');

      // For each frequency, calculate when 2nd scan has passed without Done
      // 3days: 2nd scan = day 6, warn day 6, pause day 10
      // weekly: 2nd scan = day 14, warn day 14, pause day 18
      // monthly: 2nd scan = day 60, warn day 60, pause day 64
      const freqConfig = {
        '3days':   { warnAfter: 6,  pauseAfter: 10 },
        'weekly':  { warnAfter: 14, pauseAfter: 18 },
        '1week':   { warnAfter: 14, pauseAfter: 18 },
        'monthly': { warnAfter: 60, pauseAfter: 64 },
      };
      const defaultConfig = { warnAfter: 14, pauseAfter: 18 };

      const pages = await pool.query(`
        SELECT p.*, tc.email, tc.name, tc.whatsapp, tc.callmebot_key, tc.token, tc.domain, tc.status as client_status
        FROM tracker_pages p
        JOIN tracker_clients tc ON tc.id = p.tracker_client_id
        WHERE p.tracker_client_id IS NOT NULL
        AND (p.is_active = TRUE OR p.is_active IS NULL)
        AND tc.status = 'active'
        AND p.brief_started_at IS NOT NULL
        AND (p.is_done = FALSE OR p.is_done IS NULL)
        AND p.brief_content IS NOT NULL
        AND tc.email IS NOT NULL
        AND (p.check_frequency IS NULL OR p.check_frequency NOT IN ('0','off'))
      `);

      console.log('[html-reminder] Checking', pages.rows.length, 'active briefs');

      // Group by client to avoid spamming
      const clientsSentTo = new Set();

      for (const p of pages.rows) {
        const cfg = freqConfig[p.check_frequency] || defaultConfig;
        const briefAgeDays = Math.floor((Date.now() - new Date(p.brief_started_at).getTime()) / (1000 * 60 * 60 * 24));
        const trackerUrl = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + p.token;
        const clientKey = p.tracker_client_id;

        // AUTO-PAUSE: brief age >= pauseAfter
        if (briefAgeDays >= cfg.pauseAfter) {
          console.log('[html-reminder] Auto-pausing client', p.tracker_client_id, '— brief age:', briefAgeDays, 'days');
          await pool.query(`UPDATE tracker_clients SET status='paused', paused_at=NOW() WHERE id=$1`, [p.tracker_client_id]).catch(()=>{});

          if (!clientsSentTo.has(clientKey)) {
            clientsSentTo.add(clientKey);
            const subject = 'Your ContentScale tracker has been paused — ' + p.domain;
            const htmlBody = '<h2 style="font-size:17px;font-weight:800;color:#dc2626;margin-bottom:10px;">Your tracker has been automatically paused</h2>'
              + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">Your Citation Brief for <strong>' + p.url + '</strong> has been active for <strong>' + briefAgeDays + ' days</strong> without being marked as done.</p>'
              + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">To reactivate your tracker, contact Ottmar directly.</p>'
              + '<a href="https://wa.me/31628073996?text=Hi+Ottmar,+I+want+to+reactivate+my+tracker+for+' + encodeURIComponent(p.domain) + '" style="display:inline-block;background:#16a34a;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">WhatsApp Ottmar to reactivate &rarr;</a>'
              + '<p style="font-size:11px;color:#94a3b8;margin-top:12px;">Or let Ottmar implement everything for you — high-GRAAF, citation-ready content.</p>';
            await notifyClient(p.tracker_client_id, subject, htmlBody, subject + '\n\n<a href="' + trackerUrl + '">View tracker →</a>').catch(()=>{});

            if (p.telegram_chat_id) {
            await sendTelegramNotification(p.telegram_chat_id, '⏸️ Your ContentScale tracker for ').catch(()=>{});
          }
          }
          continue;
        }

        // WARNING: brief age >= warnAfter (2nd scan passed, 4 days until pause)
        if (briefAgeDays >= cfg.warnAfter && !clientsSentTo.has(clientKey)) {
          clientsSentTo.add(clientKey);
          const daysLeft = cfg.pauseAfter - briefAgeDays;
          console.log('[html-reminder] Warning client', p.tracker_client_id, '—', daysLeft, 'days until pause');

          const subject = '⚠️ Your tracker pauses in ' + daysLeft + ' days — ' + p.domain;
          const htmlBody = '<h2 style="font-size:17px;font-weight:800;color:#d97706;margin-bottom:10px;">Action needed — tracker pauses in ' + daysLeft + ' days</h2>'
            + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">Your Citation Brief for <strong>' + p.url + '</strong> has been active for <strong>' + briefAgeDays + ' days</strong> without being marked as done. If no action is taken, your tracker will be automatically paused.</p>'
            + '<div style="background:#fef3c7;border:1px solid #fde68a;border-radius:8px;padding:14px 16px;margin-bottom:16px;font-size:13px;color:#92400e;">'
            + '<strong>To keep your tracker active:</strong><br>1. Implement at least the HIGH priority recommendation<br>2. Press <strong>Done</strong> in your tracker<br>3. Paste your updated page HTML'
            + '</div>'
            + '<a href="' + trackerUrl + '" style="display:inline-block;background:#7c3aed;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;margin-right:10px;">View tracker &rarr;</a>'
            + '<a href="https://wa.me/31628073996?text=Hi+Ottmar,+please+implement+my+Citation+Brief+for+' + encodeURIComponent(p.url) + '" style="display:inline-block;background:#16a34a;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">Let Ottmar do it for me &rarr;</a>'
            + '<p style="font-size:11px;color:#94a3b8;margin-top:14px;">Done-for-you AI citation optimization — high-GRAAF, citation-ready content.</p>';
          await notifyClient(p.tracker_client_id, subject, htmlBody, subject + '\n\n<a href="' + trackerUrl + '">View tracker →</a>', true).catch(()=>{});

          if (p.telegram_chat_id) {
            await sendTelegramNotification(p.telegram_chat_id, '⚠️ Your ContentScale tracker for ').catch(()=>{});
          }
          await new Promise(r => setTimeout(r, 2000));
          continue;
        }

        // REMINDER: needs_html=TRUE (Done pressed, HTML not pasted)
        if (p.needs_html && !clientsSentTo.has(clientKey)) {
          clientsSentTo.add(clientKey);
          const subject = 'Reminder: paste your updated HTML — ' + p.domain;
          const htmlBody = '<h2 style="font-size:17px;font-weight:800;color:#0f172a;margin-bottom:10px;">Your tracker is waiting for new HTML</h2>'
            + '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">You pressed Done — great! The system now needs the <strong>updated HTML</strong> of <strong>' + p.url + '</strong> to measure your improvements and generate the next Citation Brief.</p>'
            + '<div style="background:#fefce8;border:1px solid #fde047;border-radius:8px;padding:14px 16px;margin-bottom:16px;font-size:13px;color:#854d0e;">'
            + '1. Open <strong>' + p.url + '</strong> in Chrome &rarr; Right-click &rarr; View Page Source<br>'
            + '2. Ctrl+A &rarr; Ctrl+C &rarr; Go to tracker &rarr; click <strong>Paste new HTML</strong>'
            + '</div>'
            + '<a href="' + trackerUrl + '" style="display:inline-block;background:#7c3aed;color:white;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">View tracker &rarr;</a>';
          await notifyClient(p.tracker_client_id, subject, htmlBody, subject + '\n\n<a href="' + trackerUrl + '">View tracker →</a>', true).catch(()=>{});

          if (p.telegram_chat_id) {
            await sendTelegramNotification(p.telegram_chat_id, '⚠️ Paste updated HTML for ').catch(()=>{});
          }
          await new Promise(r => setTimeout(r, 2000));
        }
      }

      console.log('[html-reminder] Done. Sent to', clientsSentTo.size, 'clients.');
    } catch(e) { console.warn('[html-reminder]', e.message); }

    setTimeout(runHtmlReminder, 24 * 60 * 60 * 1000);
  }, 5 * 60 * 1000);
  console.log('[html-reminder] Frequency-aware reminder + auto-pause scheduler started');
}

startHtmlReminderScheduler();

let _trackerSchedulerTimer = null;
function startTrackerScheduler() {
  if(_trackerSchedulerTimer) return;
  _trackerSchedulerTimer = setInterval(async () => {
    if (process.env.ENABLE_TRACKER_SCHEDULER !== '1') return;  // SAFETY: auto SERP/Serper scanning OFF unless explicitly enabled (prevents silent Serper credit drain)
    if(!pool) return;
    try {
      // Pick pages from BOTH engine tracker (engine_code_id) AND client tracker (tracker_client_id)
      const due = await pool.query(
        `SELECT p.* FROM tracker_pages p
         WHERE (p.is_active = TRUE OR p.is_active IS NULL)
         AND (p.engine_code_id IS NOT NULL OR p.tracker_client_id IS NOT NULL)
         AND (
           (p.engine_code_id IS NOT NULL AND (p.check_frequency IS NULL OR p.check_frequency NOT IN ('0','0days','off')) AND (p.next_check_at <= NOW() OR p.next_check_at IS NULL))
           OR
           (p.tracker_client_id IS NOT NULL AND p.last_checked_at IS NOT NULL AND p.next_check_at IS NOT NULL AND p.next_check_at <= NOW() AND (p.check_frequency IS NULL OR p.check_frequency NOT IN ('0','0days','off')))
         )
         ORDER BY
           CASE p.check_frequency
             WHEN 'daily' THEN 1
             WHEN '1day' THEN 1
             WHEN '3days' THEN 2
             WHEN 'weekly' THEN 3
             WHEN '1week' THEN 3
             ELSE 4
           END,
           p.next_check_at ASC NULLS FIRST
         LIMIT 10`
      );
      for(const page of due.rows) {
        const source = page.tracker_client_id ? 'client' : 'engine';
        const _sk = { gemini: process.env.GEMINI_API_KEY, serpapiKey: process.env.SERPAPI_KEY, youKey: process.env.YOU_API_KEY, perplexityKey: process.env.PERPLEXITY_API_KEY };

        // ── CLIENT TRACKER: respect needs_html flag ──────────────────────
        if (page.tracker_client_id) {
          // If user needs to provide new HTML, skip scan and push next_check out
          if (page.needs_html === true || page.needs_html === 't' || page.needs_html === 1) {
            console.log('[tracker-scheduler] Skipping scan for', page.url, '— needs fresh HTML from user (needs_html=true)');
            // Push next check out by one frequency period so we don't keep trying
            const freqHours = { daily: 24, '1day': 24, '3days': 72, '7days': 168, weekly: 168, '1week': 168, '17days': 408, '21days': 504, '30days': 720, monthly: 720 };
            let hours = freqHours[page.check_frequency];
            if (!hours) { const _hm = String(page.check_frequency || '').match(/^(\d+)\s*days?$/); hours = _hm ? parseInt(_hm[1], 10) * 24 : 72; }
            await pool.query('UPDATE tracker_pages SET next_check_at = NOW() + INTERVAL \'' + hours + ' hours\' WHERE id=$1', [page.id]).catch(()=>{});
            continue;
          }

          // If no HTML content at all, skip scan
          if (!page.html_content) {
            console.log('[tracker-scheduler] Skipping scan for', page.url, '— no HTML content available');
            continue;
          }

          // ── HTML freshness check: detect changes, notify, but DON'T auto-scan ──
          if (page.last_page_hash) {
            try {
              const liveResp = await fetch(page.url, { headers: { 'User-Agent': 'Mozilla/5.0' }, signal: AbortSignal.timeout(10000) });
              if (liveResp.ok) {
                const liveHtml = await liveResp.text();
                const crypto = require('crypto');
                const liveHashMd5 = crypto.createHash('md5').update(liveHtml).digest('hex');

                if (liveHashMd5 !== page.last_page_hash) {
                  console.log('[tracker-scheduler] HTML change detected for', page.url, '— marking needs_html=true');
                  // Mark as needing fresh HTML — DON'T auto-fetch and scan
                  await pool.query('UPDATE tracker_pages SET needs_html=TRUE, next_check_at = NOW() + INTERVAL \'72 hours\' WHERE id=$1', [page.id]).catch(()=>{});
                  // Notify user ONCE (max once per 24h)
                  const clientR2 = await pool.query('SELECT * FROM tracker_clients WHERE id=$1', [page.tracker_client_id]);
                  const client2 = clientR2.rows[0];
                  if (client2) {
                    const lastNotify = page.html_mismatch_notified_at;
                    const oneDayAgo = new Date(Date.now() - 86400000);
                    if (!lastNotify || new Date(lastNotify) < oneDayAgo) {
                      await pool.query('UPDATE tracker_pages SET html_mismatch_notified_at = NOW() WHERE id=$1', [page.id]).catch(()=>{});
                      const trackerUrl2 = (process.env.APP_URL || 'https://app.contentscale.site') + '/track/' + client2.token;
                      if (client2.email) {
                        await sendTrackerEmail(page.tracker_client_id,
                          'Your page changed — paste new HTML for next scan — ' + client2.domain,
                          '<p style="font-size:14px;color:#374151;line-height:1.7;margin-bottom:14px;">Your page <strong>' + page.url + '</strong> has changed online. To get an accurate scan, please paste your updated page HTML into the tracker.</p><p style="font-size:13px;color:#6b7280;line-height:1.6;margin-bottom:14px;">The orange <strong>HTML</strong> button on your page card is now blinking — click it to paste your fresh HTML.</p>'
                          + '<a href="' + trackerUrl2 + '" style="display:inline-block;background:#f59e0b;color:#0a0a12;text-decoration:none;padding:10px 22px;border-radius:6px;font-size:13px;font-weight:700;">Paste New HTML →</a>'
                        , true).catch(()=>{});
                      }
                      if (client2.telegram_chat_id) {
                        await sendTelegramNotification(client2.telegram_chat_id, '🔄 <b>' + page.url + '</b> changed online. Paste fresh HTML in your tracker for the next scan.').catch(()=>{});
                      }
                    }
                  }
                  continue; // SKIP scan — wait for user to provide new HTML
                } else {
                  console.log('[tracker-scheduler] HTML unchanged for', page.url, '— proceeding with scan');
                }
              }
            } catch(hashErr) {
              console.warn('[tracker-scheduler] Hash check failed for', page.url, ':', hashErr.message);
            }
          }
        }

        console.log('[tracker-scheduler] Running check for:', page.url, '| source:', source, '| freq:', page.check_frequency);
        await runTrackerCheck(page, _sk.gemini, _sk).catch(e => console.warn('[tracker-scheduler]', e.message));
        await new Promise(r => setTimeout(r, 5000));
      }
    } catch(e) { console.warn('[tracker-scheduler]', e.message); }
  }, (parseInt(process.env.TRACKER_SCHEDULER_MIN, 10) || 30) * 60 * 1000);
  const _schedMin = parseInt(process.env.TRACKER_SCHEDULER_MIN, 10) || 30;
  console.log('[tracker-scheduler] '+(process.env.ENABLE_TRACKER_SCHEDULER==='1'?('ENABLED (every '+_schedMin+'min)'):'DISABLED (set ENABLE_TRACKER_SCHEDULER=1 to turn on auto-scans)'));
  console.log('[tracker-keys] SERPAPI_KEY:', !!process.env.SERPAPI_KEY, '| SERPER_API_KEY:', !!process.env.SERPER_API_KEY, '| GEMINI:', !!process.env.GEMINI_API_KEY, '| PERPLEXITY:', !!process.env.PERPLEXITY_API_KEY);
}





